const money = lazyIntl.number({ style: "currency", currency: "EGP", maximumFractionDigits: 0 });
const NO_COUPON = "__none";

type Props = {
  cart: AbandonedCartRow | null;
  storeName: string;
  storeBaseUrl: string;
  coupons: { code: string; label: string }[];
};

/** URL-driven (`?cart=<key>`): everything needed to win the cart back. */
export function RecoverDialog(props: Props) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  function close() {
    const next = new URLSearchParams(searchParams.toString());
    next.delete("cart");
    const query = next.toString();
    router.replace(query ? `${pathname}?${query}` : pathname, { scroll: false });
  }

  return (
    <Dialog open={Boolean(props.cart)} onOpenChange={(o) => !o && close()}>
      <DialogContent dir={tdir()} className="max-h-[90dvh] overflow-y-auto sm:max-w-lg">
        {props.cart && <RecoverPanel key={props.cart.key} {...props} cart={props.cart} />}
      </DialogContent>
    </Dialog>
  );
}

function buildMessage(cart: AbandonedCartRow, storeName: string, link: string, coupon: string | null) {
  const first = cart.fullName?.trim().split(/\s+/)[0];
  const lines = cart.items.slice(0, 3).map((i) => `• ${i.name}${i.quantity > 1 ? ` (×${i.quantity})` : ""}`);
  if (cart.items.length > 3) lines.push(tr("• و{0} منتج تاني", cart.items.length - 3));
  return [
    tr("أهلاً{0} 👋", first ? ` ${first}` : ""),
    tr("لاحظنا إن في منتجات مستنياك في سلتك في {0}:", storeName),
    ...lines,
    coupon ? tr("\nوعشانك، ليك خصم بالكود {0} 🎁 هيتطبق لوحده.", coupon) : "",
    tr("\nكمّل طلبك من هنا 👇\n{0}", link),
  ]
    .filter(Boolean)
    .join("\n");
}

function RecoverPanel({ cart, storeName, storeBaseUrl, coupons }: Props & { cart: AbandonedCartRow }) {
  const router = useRouter();
  const [token, setToken] = useState<string | null>(null);
  const [linkError, setLinkError] = useState<string | null>(null);
  const [coupon, setCoupon] = useState(NO_COUPON);
  const [edited, setEdited] = useState<string | null>(null);
  const [copied, setCopied] = useState<"msg" | "link" | null>(null);
  const [pending, startTransition] = useTransition();
  const recovered = cart.status === "recovered";

  useEffect(() => {
    if (recovered) return;
    let cancelled = false;
    GetRecoveryLinkTokenAction(cart.key)
      .then((r) => {
        if (cancelled) return;
        if (r.ok) setToken(r.token);
        else setLinkError(r.message);
      })
      .catch(() => !cancelled && setLinkError(tr("مقدرناش نجهّز اللينك.")));
    return () => {
      cancelled = true;
    };
  }, [cart.key, recovered]);

  const link = token
    ? `${storeBaseUrl}/cart?restore=${token}${coupon !== NO_COUPON ? `&coupon=${encodeURIComponent(coupon)}` : ""}`
    : "";
  const generated = useMemo(
    () => (link ? buildMessage(cart, storeName, link, coupon === NO_COUPON ? null : coupon) : ""),
    [cart, storeName, link, coupon],
  );
  const message = edited ?? generated;

  function markContacted() {
    startTransition(async () => {
      await MarkCartContactedAction(cart.key);
      router.refresh();
    });
  }

  function sendWhatsApp() {
    if (!cart.phone) return;
    window.open(`https://wa.me/${toWhatsAppDigits(cart.phone)}?text=${encodeURIComponent(message)}`, "_blank", "noopener");
    markContacted();
    toast.success(tr("اتفتح الواتساب — اتسجلت إنك تواصلت"));
  }

  function copy(text: string, what: "msg" | "link") {
    navigator.clipboard?.writeText(text).catch(() => {});
    setCopied(what);
    setTimeout(() => setCopied(null), 1500);
  }

  const meta = recoveryMeta(cart.status);

  return (
    <div className="min-w-0 space-y-5">
      <DialogHeader className="text-start sm:text-start">
        <div className="flex items-center gap-2">
          <DialogTitle>{cart.fullName || (cart.phone ? tr("عميل") : tr("زائر من غير رقم"))}</DialogTitle>
          <StatusPill tone={meta.tone}>{meta.label}</StatusPill>
        </div>
        <DialogDescription>
          {cart.phone ? (
            <span className="font-mono" dir="ltr">
              {cart.phone}
            </span>
          ) : (
            tr("مسابش رقمه — تقدر تبعتله اللينك لو بيكلمك على إنستجرام أو ماسنجر.")
          )}
          {cart.contactCount > 0 && tr(" · اتواصلت {0} مرة", cart.contactCount)}
        </DialogDescription>
      </DialogHeader>

      {recovered ? (
        <div className="space-y-3 rounded-lg border border-emerald-500/30 bg-emerald-500/5 p-4 text-sm">
          <p className="font-medium">{tr("رجع وطلب بـ {0} بعد ما تواصلت معاه 🎉", money.format(cart.value / 100))}</p>
          {cart.orderId && (
            <Button asChild size="sm" variant="outline" className="gap-1.5">
              <Link href={`/orders/${cart.orderId}`}>
                <ExternalLink className="size-4" />
                {tr("افتح الطلب")}
              </Link>
            </Button>
          )}
        </div>
      ) : (
        <>
          <ul className="divide-y divide-border rounded-lg border border-border">
            {cart.items.map((item) => (
              <li key={item.productId} className="flex items-center gap-3 p-2.5">
                <span className="size-10 shrink-0 overflow-hidden rounded-md bg-muted">
                  {item.image && (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={item.image} alt="" className="size-full object-cover" />
                  )}
                </span>
                <span className="min-w-0 flex-1 truncate text-sm">{item.name}</span>
                <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
                  {item.quantity} × {money.format(item.price / 100)}
                </span>
              </li>
            ))}
            <li className="flex items-center justify-between bg-muted/40 px-3 py-2 text-sm">
              <span className="text-muted-foreground">{tr("الإجمالي")}</span>
              <span className="font-semibold tabular-nums">{money.format(cart.value / 100)}</span>
            </li>
          </ul>

          {coupons.length > 0 && (
            <div className="space-y-2">
              <Label>{tr("تضيف كود خصم؟")}</Label>
              <Select
                value={coupon}
                onValueChange={(v) => {
                  setCoupon(v);
                  setEdited(null);
                }}
                dir={tdir()}
              >
                <SelectTrigger className="w-full">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value={NO_COUPON}>{tr("من غير خصم")}</SelectItem>
                  {coupons.map((c) => (
                    <SelectItem key={c.code} value={c.code}>
                      <span className="font-mono" dir="ltr">
                        {c.code}
                      </span>{" "}
                      <span className="text-muted-foreground">· {c.label}</span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">{tr("الكود بيتطبق لوحده لما يفتح اللينك.")}</p>
            </div>
          )}

          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label htmlFor="recover-message">{tr("الرسالة")}</Label>
              {edited !== null && (
                <button type="button" className="text-xs text-primary hover:underline" onClick={() => setEdited(null)}>
                  {tr("رجّع الرسالة الأصلية")}
                </button>
              )}
            </div>
            {linkError ? (
              <p className="rounded-lg bg-muted p-3 text-sm text-muted-foreground">{linkError}</p>
            ) : !token ? (
              <div className="grid h-40 place-items-center rounded-lg border border-border">
                <Loader2 className="size-4 animate-spin text-muted-foreground" />
              </div>
            ) : (
              <Textarea
                id="recover-message"
                rows={8}
                value={message}
                onChange={(e) => setEdited(e.target.value)}
                className="resize-none text-sm leading-6"
              />
            )}
          </div>

          <div className="flex flex-wrap gap-2">
            {cart.phone && (
              <Button onClick={sendWhatsApp} disabled={!token || pending} className="gap-1.5 bg-[#25D366] text-white hover:bg-[#1ebe5b]">
                <WhatsAppIcon className="size-4" />
                {tr("ابعت على واتساب")}
              </Button>
            )}
            <Button variant="outline" className="gap-1.5" disabled={!token} onClick={() => copy(message, "msg")}>
              {copied === "msg" ? <Check className="size-4" /> : <Copy className="size-4" />}
              {tr("انسخ الرسالة")}
            </Button>
            <Button variant="ghost" className="gap-1.5" disabled={!token} onClick={() => copy(link, "link")}>
              {copied === "link" ? <Check className="size-4" /> : <Copy className="size-4" />}
              {tr("اللينك بس")}
            </Button>
            {cart.phone && (
              <Button asChild variant="ghost" size="icon" aria-label={tr("اتصال")}>
                <a href={`tel:${cart.phone}`} onClick={markContacted}>
                  <Phone className="size-4" />
                </a>
              </Button>
            )}
          </div>
          {!cart.phone && token && (
            <button type="button" className="text-xs text-muted-foreground hover:text-foreground hover:underline" onClick={markContacted}>
              {tr("بعتهاله بطريقة تانية؟ علّمها إنك تواصلت")}
            </button>
          )}
        </>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { formatDistanceToNow } from "date-fns";
import { ar } from "date-fns/locale";
import {
  Plus,
  MoreHorizontal,
  ShieldOff,
  RefreshCw,
  Copy,
  CheckCircle2,
  AlertCircle,
  Code2,
  Clock,
} from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

import { revokeApiKey, rotateApiKey } from "@/actions/api-keys/manage.actions";
import CreateKeyDialog from "./CreateKeyDialog";
import KeyRevealDialog from "./KeyRevealDialog";
import { tdir, tr } from "@/lib/i18n/dashboard";

type ApiKey = {
  id: string;
  name: string;
  keyHint: string;
  status: string;
  scopes: string[];
  ipWhitelist: string[];
  lastUsedAt: Date | null;
  expiresAt: Date | null;
  createdAt: Date;
  revokedAt: Date | null;
};

interface Props {
  storeId: string;
  initialKeys: ApiKey[];
}

export default function ApiKeysClient({ storeId, initialKeys }: Props) {
  const [keys, setKeys] = useState<ApiKey[]>(initialKeys);
  const [createOpen, setCreateOpen] = useState(false);
  const [newKey, setNewKey] = useState<{ key: string; name: string } | null>(null);
  const [revokeTarget, setRevokeTarget] = useState<ApiKey | null>(null);
  const [isPending, startTransition] = useTransition();

  function handleKeyCreated(rawKey: string, name: string, keyRecord: ApiKey) {
    setKeys((prev) => [keyRecord, ...prev]);
    setNewKey({ key: rawKey, name });
    setCreateOpen(false);
  }

  function handleRevoke() {
    if (!revokeTarget) return;
    const id = revokeTarget.id;
    setRevokeTarget(null);

    startTransition(async () => {
      try {
        await revokeApiKey(id, storeId);
        setKeys((prev) =>
          prev.map((k) =>
            k.id === id ? { ...k, status: "REVOKED", revokedAt: new Date() } : k,
          ),
        );
        toast.success(tr("تم إلغاء المفتاح بنجاح"));
      } catch {
        toast.error(tr("حدث خطأ، يرجى المحاولة مرة أخرى"));
      }
    });
  }

  function handleRotate(key: ApiKey) {
    startTransition(async () => {
      try {
        const { key: rawKey, id: newId } = await rotateApiKey(key.id, storeId);
        setKeys((prev) =>
          prev
            .map((k) => (k.id === key.id ? { ...k, status: "REVOKED", revokedAt: new Date() } : k))
            .concat([
              {
                ...key,
                id: newId,
                status: "ACTIVE",
                revokedAt: null,
                lastUsedAt: null,
                createdAt: new Date(),
              },
            ]),
        );
        setNewKey({ key: rawKey, name: tr("{0} (جديد)", key.name) });
        toast.success(tr("تم تجديد المفتاح بنجاح"));
      } catch {
        toast.error(tr("حدث خطأ، يرجى المحاولة مرة أخرى"));
      }
    });
  }

  const activeKeys = keys.filter((k) => k.status === "ACTIVE");
  const revokedKeys = keys.filter((k) => k.status === "REVOKED");

  return (
    <>
      {/* Info + create button */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between pb-4">
          <div>
            <CardTitle className="text-base">{tr("المفاتيح النشطة")}</CardTitle>
            <CardDescription className="mt-1">
              {tr("استخدم مفتاح API للاتصال بنظام Casho برمجياً من أنظمتك الخارجية")}
            </CardDescription>
          </div>
          <Button
            size="sm"
            className="rounded-xl gap-1.5"
            onClick={() => setCreateOpen(true)}
            disabled={activeKeys.length >= 10}
          >
            <Plus className="size-4" />
            {tr("مفتاح جديد")}
          </Button>
        </CardHeader>

        <CardContent className="space-y-3">
          {/* Endpoint hint */}
          <div className="flex items-center gap-2 rounded-lg border bg-muted/40 px-3 py-2 font-mono text-xs text-muted-foreground">
            <Code2 className="size-3.5 shrink-0" />
            <span dir="ltr">Authorization: Bearer csk_live_••••••••</span>
          </div>

          {activeKeys.length === 0 ? (
            <div className="flex flex-col items-center gap-2 py-8 text-center text-sm text-muted-foreground">
              <Code2 className="size-8 text-muted-foreground/40" />
              <p>{tr("لا توجد مفاتيح نشطة")}</p>
              <p className="text-xs">{tr("أنشئ مفتاحاً للبدء في استخدام API")}</p>
            </div>
          ) : (
            <div className="divide-y rounded-xl border">
              {activeKeys.map((key) => (
                <KeyRow
                  key={key.id}
                  apiKey={key}
                  onRevoke={() => setRevokeTarget(key)}
                  onRotate={() => handleRotate(key)}
                  disabled={isPending}
                />
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Revoked keys (collapsed) */}
      {revokedKeys.length > 0 && (
        <Card className="opacity-60">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              {tr("المفاتيح الملغاة ({0})", revokedKeys.length)}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="divide-y rounded-xl border">
              {revokedKeys.map((key) => (
                <KeyRow key={key.id} apiKey={key} revoked />
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Dialogs */}
      <CreateKeyDialog
        open={createOpen}
        storeId={storeId}
        onOpenChange={setCreateOpen}
        onCreated={handleKeyCreated}
      />

      <KeyRevealDialog
        open={!!newKey}
        rawKey={newKey?.key ?? ""}
        name={newKey?.name ?? ""}
        onClose={() => setNewKey(null)}
      />

      <AlertDialog open={!!revokeTarget} onOpenChange={(o) => !o && setRevokeTarget(null)}>
        <AlertDialogContent dir={tdir()}>
          <AlertDialogHeader>
            <AlertDialogTitle>{tr("إلغاء المفتاح")}</AlertDialogTitle>
            <AlertDialogDescription>
              {tr("سيتوقف المفتاح")}{" "}<strong>{revokeTarget?.name}</strong>{" "}{tr("عن العمل فوراً. هذا الإجراء لا يمكن التراجع عنه.")}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="flex-row-reverse justify-start gap-2">
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={handleRevoke}
            >
              {tr("إلغاء المفتاح")}
            </AlertDialogAction>
            <AlertDialogCancel>{tr("تراجع")}</AlertDialogCancel>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

// ─── Key row ──────────────────────────────────────────────────────────────────

function KeyRow({
  apiKey,
  onRevoke,
  onRotate,
  disabled,
  revoked,
}: {
  apiKey: ApiKey;
  onRevoke?: () => void;
  onRotate?: () => void;
  disabled?: boolean;
  revoked?: boolean;
}) {
  return (
    <div className="flex items-center gap-3 px-4 py-3">
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="truncate text-sm font-medium">{apiKey.name}</span>
          {apiKey.status === "ACTIVE" ? (
            <CheckCircle2 className="size-3.5 shrink-0 text-emerald-500" />
          ) : (
            <ShieldOff className="size-3.5 shrink-0 text-muted-foreground" />
          )}
        </div>

        <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1">
          <span className="font-mono text-xs text-muted-foreground" dir="ltr">
            csk_live_••••{apiKey.keyHint}
          </span>

          {apiKey.scopes.length === 0 ? (
            <Badge variant="secondary" className="rounded-md px-1.5 py-0 text-xs">
              {tr("كل الصلاحيات")}
            </Badge>
          ) : (
            <span className="text-xs text-muted-foreground">
              {tr("{0} صلاحية", apiKey.scopes.length)}
            </span>
          )}

          {apiKey.lastUsedAt ? (
            <span className="flex items-center gap-1 text-xs text-muted-foreground">
              <Clock className="size-3" />
              {tr("آخر استخدام {0}", formatDistanceToNow(apiKey.lastUsedAt, { addSuffix: true, locale: ar }))}
            </span>
          ) : (
            <span className="text-xs text-muted-foreground/60">{tr("لم يُستخدم بعد")}</span>
          )}
        </div>
      </div>

      {!revoked && (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon" className="size-8 shrink-0" disabled={disabled}>
              <MoreHorizontal className="size-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start">
            <DropdownMenuItem onClick={onRotate}>
              <RefreshCw className="me-2 size-4" />
              {tr("تجديد المفتاح")}
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-destructive focus:text-destructive"
              onClick={onRevoke}
            >
              <ShieldOff className="me-2 size-4" />
              {tr("إلغاء المفتاح")}
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import { createApiKey } from "@/actions/api-keys/manage.actions";
import { SCOPES, type ApiScope } from "@/lib/api/types";
import { tdir, tr } from "@/lib/i18n/dashboard";

const SCOPE_LABELS: Record<ApiScope, string> = {
  get "orders:read"() { return tr("قراءة الطلبات"); },
  get "orders:write"() { return tr("إنشاء وتعديل الطلبات"); },
  get "customers:read"() { return tr("قراءة العملاء"); },
  get "customers:write"() { return tr("إنشاء وتعديل العملاء"); },
  get "products:read"() { return tr("قراءة المنتجات"); },
  get "shipments:read"() { return tr("قراءة الشحنات"); },
  get "shipments:write"() { return tr("إنشاء وإلغاء الشحنات"); },
  get "webhooks:read"() { return tr("قراءة Webhooks"); },
  get "webhooks:write"() { return tr("إنشاء وحذف Webhooks"); },
};

const SCOPE_GROUPS = [
  { get label() { return tr("الطلبات"); }, scopes: ["orders:read", "orders:write"] as ApiScope[] },
  { get label() { return tr("العملاء"); }, scopes: ["customers:read", "customers:write"] as ApiScope[] },
  { get label() { return tr("المنتجات"); }, scopes: ["products:read"] as ApiScope[] },
  { get label() { return tr("الشحن"); }, scopes: ["shipments:read", "shipments:write"] as ApiScope[] },
  { label: "Webhooks", scopes: ["webhooks:read", "webhooks:write"] as ApiScope[] },
];

interface Props {
  open: boolean;
  storeId: string;
  onOpenChange: (open: boolean) => void;
  onCreated: (
    rawKey: string,
    name: string,
    keyRecord: {
      id: string;
      name: string;
      keyHint: string;
      status: string;
      scopes: string[];
      ipWhitelist: string[];
      lastUsedAt: null;
      expiresAt: null;
      createdAt: Date;
      revokedAt: null;
    },
  ) => void;
}

export default function CreateKeyDialog({ open, storeId, onOpenChange, onCreated }: Props) {
  const [name, setName] = useState("");
  const [allScopes, setAllScopes] = useState(true);
  const [selectedScopes, setSelectedScopes] = useState<Set<ApiScope>>(new Set());
  const [ipWhitelist, setIpWhitelist] = useState("");
  const [isPending, startTransition] = useTransition();

  function toggleScope(scope: ApiScope) {
    setSelectedScopes((prev) => {
      const next = new Set(prev);
      next.has(scope) ? next.delete(scope) : next.add(scope);
      return next;
    });
  }

  function handleSubmit() {
    if (!name.trim()) {
      toast.error(tr("الرجاء إدخال اسم للمفتاح"));
      return;
    }

    const scopes = allScopes ? [] : (Array.from(selectedScopes) as ApiScope[]);
    const ips = ipWhitelist
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);

    startTransition(async () => {
      try {
        const { key, id } = await createApiKey(storeId, name.trim(), scopes, ips);

        const keyRecord = {
          id,
          name: name.trim(),
          keyHint: key.slice(-8),
          status: "ACTIVE",
          scopes,
          ipWhitelist: ips,
          lastUsedAt: null as null,
          expiresAt: null as null,
          createdAt: new Date(),
          revokedAt: null as null,
        };

        onCreated(key, name.trim(), keyRecord);

        // Reset form
        setName("");
        setAllScopes(true);
        setSelectedScopes(new Set());
        setIpWhitelist("");
      } catch (e) {
        toast.error(e instanceof Error ? e.message : tr("حدث خطأ"));
      }
    });
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent dir={tdir()} className="max-w-md">
        <DialogHeader>
          <DialogTitle>{tr("إنشاء مفتاح API جديد")}</DialogTitle>
          <DialogDescription>
            {tr("سيتم عرض المفتاح مرة واحدة فقط بعد الإنشاء — احتفظ به في مكان آمن.")}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 py-2">
          {/* Name */}
          <div className="space-y-1.5">
            <Label htmlFor="key-name">{tr("اسم المفتاح")}</Label>
            <Input
              id="key-name"
              placeholder={tr("مثال: نظام ERP الخارجي")}
              value={name}
              onChange={(e) => setName(e.target.value)}
              disabled={isPending}
            />
          </div>

          {/* Scopes */}
          <div className="space-y-3">
            <Label>{tr("الصلاحيات")}</Label>

            <div className="flex items-center gap-2">
              <Checkbox
                id="all-scopes"
                checked={allScopes}
                onCheckedChange={(v) => setAllScopes(!!v)}
                disabled={isPending}
              />
              <label htmlFor="all-scopes" className="cursor-pointer text-sm font-medium">
                {tr("كل الصلاحيات (غير موصى به للإنتاج)")}
              </label>
            </div>

            {!allScopes && (
              <div className="rounded-xl border p-3 space-y-3">
                {SCOPE_GROUPS.map((group) => (
                  <div key={group.label}>
                    <p className="mb-1.5 text-xs font-semibold text-muted-foreground">
                      {group.label}
                    </p>
                    <div className="space-y-1.5">
                      {group.scopes.map((scope) => (
                        <div key={scope} className="flex items-center gap-2">
                          <Checkbox
                            id={scope}
                            checked={selectedScopes.has(scope)}
                            onCheckedChange={() => toggleScope(scope)}
                            disabled={isPending}
                          />
                          <label
                            htmlFor={scope}
                            className="cursor-pointer text-sm text-muted-foreground"
                          >
                            {SCOPE_LABELS[scope]}
                          </label>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* IP Whitelist */}
          <div className="space-y-1.5">
            <Label htmlFor="ip-list">{tr("قائمة IPs المسموح بها (اختياري)")}</Label>
            <Input
              id="ip-list"
              placeholder="192.168.1.1, 10.0.0.1"
              value={ipWhitelist}
              onChange={(e) => setIpWhitelist(e.target.value)}
              disabled={isPending}
              dir="ltr"
            />
            <p className="text-xs text-muted-foreground">
              {tr("افصل بين العناوين بفاصلة. اتركه فارغاً للسماح لجميع العناوين.")}
            </p>
          </div>
        </div>

        <DialogFooter className="flex-row-reverse gap-2 sm:gap-0">
          <Button onClick={handleSubmit} disabled={isPending}>
            {isPending && <Loader2 className="me-2 size-4 animate-spin" />}
            {tr("إنشاء المفتاح")}
          </Button>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isPending}>
            {tr("إلغاء")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Check, Copy, CreditCard, ImagePlus, Landmark, Loader2, ShieldCheck, Smartphone, Wallet, X, Zap } from "lucide-react";
import { toast } from "sonner";
import type { TopupMethod } from "@prisma/client";

import { CreateTopupRequestAction, InitiateKashierTopupAction } from "@/actions/balance/topup.actions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { TOPUP_METHODS } from "@/constants/topup";
import { formatMoney } from "@/lib/balance-ui/meta";
import { uploadImageToCloudinary } from "@/lib/cloudinary-upload";
import { cn } from "@/lib/utils";
import { lazyIntl, tr, trv } from "@/lib/i18n/dashboard";

const MIN_EGP = 10;
const nf = lazyIntl.number();
const df = lazyIntl.date({ timeZone: "Africa/Cairo", day: "numeric", month: "long", year: "numeric" });
const METHOD_ICONS: Record<string, typeof Smartphone> = { VODAFONE_CASH: Smartphone, INSTAPAY: Wallet, BANK_TRANSFER: Landmark };

type Props = {
  storeId: string;
  balance: number;
  price: number;
  periodDays: number;
  cycleWord: string;
  nextRenewal: string | null;
  initialAmount: number | null;
};

/** "حوّل على الرقم: 010…" → "010…" (what people actually need to copy). */
const accountOf = (instructions: string) => instructions.split(":").slice(1).join(":").trim() || instructions;

export function TopupStudio({ storeId, balance, price, periodDays, cycleWord, nextRenewal, initialAmount }: Props) {
  const router = useRouter();
  const shortBy = Math.max(0, price - balance);
  const presets = useMemo(() => {
    const list: { egp: number; label: string }[] = [];
    if (price > 0) {
      if (shortBy > 0) list.push({ egp: Math.max(MIN_EGP, Math.ceil(shortBy / 100)), label: tr("يكمّل التجديد الجاي") });
      list.push({ egp: Math.ceil((price * 3) / 100), label: tr("٣ {0}", cycleWord === "سنة" ? tr("سنين") : tr("شهور")) });
      list.push({ egp: Math.ceil((price * 6) / 100), label: tr("٦ {0}", cycleWord === "سنة" ? tr("سنين") : tr("شهور")) });
    }
    for (const egp of [200, 500, 1000]) if (!list.some((p) => p.egp === egp) && list.length < 5) list.push({ egp, label: "" });
    return list;
  }, [price, shortBy, cycleWord]);

  const [amount, setAmount] = useState(String(initialAmount ? Math.max(MIN_EGP, initialAmount) : (presets[0]?.egp ?? 200)));
  const [mode, setMode] = useState<"online" | "manual">("online");
  const [method, setMethod] = useState<TopupMethod>(TOPUP_METHODS[0].value);
  const [transferRef, setTransferRef] = useState("");
  const [receipt, setReceipt] = useState("");
  const [note, setNote] = useState("");
  const [uploading, setUploading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  const egp = Number(amount);
  const piasters = Number.isFinite(egp) ? Math.round(egp * 100) : 0;
  const valid = piasters >= MIN_EGP * 100;
  const after = balance + (valid ? piasters : 0);
  const renewals = price > 0 ? Math.floor(after / price) : 0;
  const coveredUntil = nextRenewal && renewals > 0 ? new Date(new Date(nextRenewal).getTime() + renewals * periodDays * 86400_000) : null;
  const selected = TOPUP_METHODS.find((m) => m.value === method)!;

  async function onReceipt(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    try {
      setUploading(true);
      setReceipt(await uploadImageToCloudinary(file, "casho/uploads/receipts", 8));
    } catch (err) {
      toast.error(err instanceof Error ? err.message : tr("فشل رفع الصورة"));
    } finally {
      setUploading(false);
    }
  }

  function payOnline() {
    setError(null);
    if (!valid) return setError(tr("أقل مبلغ {0} جنيه.", MIN_EGP));
    startTransition(async () => {
      // Redirects to Kashier on success; only returns on failure.
      const result = await InitiateKashierTopupAction(storeId, piasters);
      if (result && !result.success) setError(result.message);
    });
  }

  function submitManual() {
    setError(null);
    if (!valid) return setError(tr("أقل مبلغ {0} جنيه.", MIN_EGP));
    if (!transferRef.trim() && !receipt) return setError(tr("اكتب رقم العملية أو ارفع صورة الإيصال عشان نلاقي التحويل."));
    startTransition(async () => {
      const result = await CreateTopupRequestAction({ storeId, amount: piasters, method, transferRef, receiptImage: receipt, note });
      if (!result.success) {
        setError(result.message);
        return;
      }
      toast.success(tr("طلبك وصل — هنضيف الرصيد أول ما نتأكد من التحويل"));
      router.push("/balance");
    });
  }

  return (
    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_20rem]">
      <div className="space-y-4">
        {/* ── 1. Amount ───────────────────────────────────────── */}
        <section className="space-y-4 rounded-xl border border-border bg-card p-4">
          <h2 className="font-semibold">{tr("١. المبلغ")}</h2>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
            {presets.map((p) => (
              <button
                key={p.egp}
                type="button"
                onClick={() => setAmount(String(p.egp))}
                aria-pressed={egp === p.egp}
                className={cn(
                  "rounded-lg border p-3 text-start transition-colors",
                  egp === p.egp ? "border-primary bg-primary/5" : "border-border hover:border-foreground/30",
                )}
              >
                <span className="block text-base font-semibold tabular-nums">{formatMoney(p.egp * 100)}</span>
                {p.label && <span className="block text-xs text-muted-foreground">{p.label}</span>}
              </button>
            ))}
          </div>
          <div className="flex h-11 items-center rounded-lg border border-input bg-background focus-within:ring-2 focus-within:ring-ring/30">
            <input
              type="number"
              inputMode="decimal"
              min={MIN_EGP}
              step="any"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              aria-label={tr("مبلغ مخصص")}
              className="h-full min-w-0 flex-1 bg-transparent px-3 text-base tabular-nums outline-none"
            />
            <span className="pe-3 text-sm text-muted-foreground">{tr("جنيه")}</span>
          </div>
        </section>

        {/* ── 2. Method ───────────────────────────────────────── */}
        <section className="space-y-4 rounded-xl border border-border bg-card p-4">
          <h2 className="font-semibold">{tr("٢. طريقة الدفع")}</h2>
          <div className="grid gap-2 sm:grid-cols-2">
            <ModeCard
              active={mode === "online"}
              onClick={() => setMode("online")}
              icon={Zap}
              title={tr("دفع فوري")}
              hint={tr("كارت أو محفظة — الرصيد بيتضاف في ثانية")}
              badge={tr("الأسرع")}
            />
            <ModeCard
              active={mode === "manual"}
              onClick={() => setMode("manual")}
              icon={Landmark}
              title={tr("تحويل يدوي")}
              hint={tr("فودافون كاش أو إنستاباي أو بنك — بيتراجع يدوي")}
            />
          </div>

          {mode === "online" ? (
            <div className="flex items-start gap-3 rounded-lg bg-muted/50 p-3 text-sm">
              <ShieldCheck className="mt-0.5 size-4 shrink-0 text-emerald-600" />
              <p className="leading-6 text-muted-foreground">
                {tr("هتتحوّل لصفحة الدفع الآمنة (Kashier) — فيزا، ماستركارد، ميزة، أو محفظة إلكترونية. بعد الدفع هترجع هنا والرصيد مضاف.")}
              </p>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="grid gap-2 sm:grid-cols-3">
                {TOPUP_METHODS.map((m) => {
                  const Icon = METHOD_ICONS[m.value] ?? CreditCard;
                  return (
                    <button
                      key={m.value}
                      type="button"
                      onClick={() => setMethod(m.value)}
                      aria-pressed={method === m.value}
                      className={cn(
                        "flex items-center gap-2 rounded-lg border p-3 text-sm transition-colors",
                        method === m.value ? "border-primary bg-primary/5 font-medium" : "border-border hover:border-foreground/30",
                      )}
                    >
                      <Icon className="size-4" />
                      {m.label}
                    </button>
                  );
                })}
              </div>

              <div className="rounded-lg border border-dashed border-primary/40 bg-primary/[0.03] p-3">
                <p className="text-xs text-muted-foreground">
                  {tr("حوّل")}{" "}<span className="font-semibold text-foreground">{valid ? formatMoney(piasters) : tr("المبلغ")}</span>{" "}{tr("على {0}:", selected.label)}
                </p>
                <div className="mt-1 flex items-center justify-between gap-2">
                  <p className="font-mono text-lg font-semibold tracking-wide" dir="ltr">
                    {accountOf(selected.instructions)}
                  </p>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="h-8 gap-1"
                    onClick={() => {
                      navigator.clipboard?.writeText(accountOf(selected.instructions).split(" ")[0]).catch(() => {});
                      setCopied(true);
                      setTimeout(() => setCopied(false), 1500);
                    }}
                  >
                    {copied ? <Check className="size-4 text-emerald-600" /> : <Copy className="size-4" />}
                    {tr("نسخ")}
                  </Button>
                </div>
              </div>

              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="ref">{tr("رقم العملية")}</Label>
                  <Input id="ref" dir="ltr" value={transferRef} onChange={(e) => setTransferRef(e.target.value)} placeholder={tr("من رسالة التحويل")} />
                </div>
                <div className="space-y-2">
                  <Label>{tr("صورة الإيصال")}</Label>
                  {receipt ? (
                    <div className="flex h-10 items-center gap-2 rounded-md border border-border px-2">
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <img src={receipt} alt="" className="size-7 rounded object-cover" />
                      <span className="flex-1 text-xs text-muted-foreground">{tr("اترفعت")}</span>
                      <Button type="button" variant="ghost" size="icon" className="size-7" aria-label={tr("شيل الإيصال")} onClick={() => setReceipt("")}>
                        <X className="size-3.5" />
                      </Button>
                    </div>
                  ) : (
                    <label className="flex h-10 cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed border-border text-xs text-muted-foreground hover:bg-muted/50">
                      {uploading ? <Loader2 className="size-4 animate-spin" /> : <ImagePlus className="size-4" />}
                      {uploading ? tr("بنرفع…") : tr("ارفع سكرين شوت")}
                      <input type="file" accept="image/*" className="sr-only" onChange={onReceipt} disabled={uploading} />
                    </label>
                  )}
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="note" className="text-xs">
                  {tr("ملاحظة")}{" "}<span className="font-normal text-muted-foreground">{tr("(اختياري)")}</span>
                </Label>
                <Textarea id="note" rows={2} value={note} onChange={(e) => setNote(e.target.value)} className="resize-none" />
              </div>
            </div>
          )}
        </section>
      </div>

      {/* ── Summary ─────────────────────────────────────────────── */}
      <aside className="space-y-3 lg:sticky lg:top-20 lg:self-start">
        <section className="rounded-xl border border-border bg-card">
          <dl className="space-y-2.5 p-4 text-sm">
            <div className="flex justify-between">
              <dt className="text-muted-foreground">{tr("رصيدك دلوقتي")}</dt>
              <dd className="tabular-nums">{formatMoney(balance)}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-muted-foreground">{tr("الشحن")}</dt>
              <dd className="tabular-nums text-emerald-700 dark:text-emerald-400">+ {valid ? formatMoney(piasters) : "—"}</dd>
            </div>
            <div className="flex justify-between border-t border-border pt-2.5 font-semibold">
              <dt>{tr("الرصيد بعد الشحن")}</dt>
              <dd className="tabular-nums">{formatMoney(after)}</dd>
            </div>
          </dl>
          {price > 0 && (
            <p className="border-t border-border bg-muted/40 px-4 py-3 text-xs leading-5 text-muted-foreground">
              {renewals > 0 ? (
                <>
                  {tr("يكفي")}{" "}<span className="font-medium text-foreground">{tr("{0} تجديد", nf.format(renewals))}</span>
                  {coveredUntil && <>{" "}{tr("— متجرك شغّال لحد {0}", df.format(coveredUntil))}</>}
                </>
              ) : (
                <>{tr("لسه مش كفاية لتجديد واحد ({0})", formatMoney(price))}</>
              )}
            </p>
          )}
        </section>

        {error && <p className="rounded-lg bg-destructive/5 px-3 py-2 text-sm text-destructive">{error}</p>}

        <Button className="h-11 w-full gap-1.5" disabled={pending || uploading || !valid} onClick={mode === "online" ? payOnline : submitManual}>
          {pending && <Loader2 className="size-4 animate-spin" />}
          {mode === "online" ? tr("ادفع {0}", valid ? formatMoney(piasters) : "") : tr("ابعت طلب الشحن")}
        </Button>
        <p className="text-center text-xs text-muted-foreground">
          {mode === "online" ? tr("مش هنحفظ بيانات كارتك — الدفع كله على Kashier.") : tr("هيوصلك إشعار أول ما الرصيد يتضاف.")}
        </p>
      </aside>
    </div>
  );
}

function ModeCard({
  active,
  onClick,
  icon: Icon,
  title,
  hint,
  badge,
}: {
  active: boolean;
  onClick: () => void;
  icon: typeof Zap;
  title: string;
  hint: string;
  badge?: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={active}
      className={cn("flex gap-3 rounded-lg border p-3 text-start transition-colors", active ? "border-primary bg-primary/5" : "border-border hover:border-foreground/30")}
    >
      <span className={cn("grid size-9 shrink-0 place-items-center rounded-lg", active ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground")}>
        <Icon className="size-4" />
      </span>
      <span className="min-w-0">
        <span className="flex items-center gap-1.5 text-sm font-medium">
          {title}
          {badge && <span className="rounded bg-emerald-500/10 px-1.5 py-0.5 text-[10px] font-medium text-emerald-700 dark:text-emerald-400">{badge}</span>}
        </span>
        <span className="block text-xs leading-5 text-muted-foreground">{hint}</span>
      </span>
    </button>
  );
}

"use client";

import Image from "next/image";
import { useState, useTransition } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { Link2, Loader2, Upload, X } from "lucide-react";
import { toast } from "sonner";

import { CreateCategoryAction, UpdateCategoryAction } from "@/actions/admin/categories.actions";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { imageSource, uploadImageToCloudinary } from "@/lib/cloudinary-upload";
import { cn } from "@/lib/utils";
import { tdir, tr, trv } from "@/lib/i18n/dashboard";

export type EditableCategory = { id: string; name: string; slug: string; image: string | null };

const NAME_MAX = 60;

type CategoryFormDialogProps = {
  storeId: string;
  /** Present → edit mode. */
  category?: EditableCategory | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved?: () => void;
};

/** Add / edit a category in place — name + optional image (upload or link). */
export function CategoryFormDialog({ open, onOpenChange, ...props }: CategoryFormDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent dir={tdir()} className="sm:max-w-md">
        {/* Content unmounts on close, so each open starts from the record's current values. */}
        <CategoryForm key={props.category?.id ?? "new"} {...props} onDone={() => onOpenChange(false)} />
      </DialogContent>
    </Dialog>
  );
}

function CategoryForm({
  storeId,
  category,
  onSaved,
  onDone,
}: Omit<CategoryFormDialogProps, "open" | "onOpenChange"> & { onDone: () => void }) {
  const isEdit = Boolean(category);
  const [pending, startTransition] = useTransition();
  const [uploading, setUploading] = useState(false);
  const [name, setName] = useState(category?.name ?? "");
  const [image, setImage] = useState(category?.image ?? "");
  const [mode, setMode] = useState<"upload" | "link">("upload");
  const [error, setError] = useState<string | null>(null);

  const busy = pending || uploading;

  async function onFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    try {
      setUploading(true);
      setImage(await uploadImageToCloudinary(file, "casho/uploads/categories"));
    } catch (err) {
      toast.error(err instanceof Error ? err.message : tr("فشل رفع الصورة"));
    } finally {
      setUploading(false);
    }
  }

  function submit(e: React.FormEvent) {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) {
      setError(tr("اكتب اسم التصنيف."));
      return;
    }
    startTransition(async () => {
      const result = category
        ? await UpdateCategoryAction(category.id, storeId, trimmed, image)
        : await CreateCategoryAction(storeId, trimmed, image);
      if (!result.ok) {
        setError(result.message);
        return;
      }
      toast.success(category ? tr("اتحفظت التعديلات") : tr("اتضاف تصنيف \"{0}\"", trimmed));
      onDone();
      onSaved?.();
    });
  }

  return (
        <form onSubmit={submit} className="min-w-0 space-y-5">
          <DialogHeader className="text-start sm:text-start">
            <DialogTitle>{isEdit ? tr("تعديل التصنيف") : tr("تصنيف جديد")}</DialogTitle>
            <DialogDescription>
              {isEdit ? tr("الرابط في المتجر بيتغيّر لو غيّرت الاسم بس.") : tr("التصنيفات بتنظّم منتجاتك وبتسهّل على العميل يلاقي اللي عايزه.")}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label htmlFor="category-name">{tr("الاسم")}</Label>
              <span className="text-xs text-muted-foreground tabular-nums">
                {name.trim().length}/{NAME_MAX}
              </span>
            </div>
            <Input
              id="category-name"
              autoFocus
              value={name}
              maxLength={NAME_MAX}
              onChange={(e) => {
                setName(e.target.value);
                setError(null);
              }}
              placeholder={tr("مثال: ملابس رجالي")}
              aria-invalid={!!error || undefined}
              aria-describedby={error ? "category-error" : undefined}
              className="h-10"
            />
            {error && (
              <p id="category-error" className="text-xs text-destructive">
                {error}
              </p>
            )}
            {isEdit && category && (
              <p className="text-xs text-muted-foreground">
