                    ? Math.floor(
                        (Date.now() - new Date(c.lastOrder.createdAt).getTime()) /
                          (1000 * 60 * 60 * 24)
                      )
                    : null;

                  const health = computeHealthScore({
                    lastOrderDate: c.lastOrder?.createdAt ? new Date(c.lastOrder.createdAt) : null,
                    orderCount: c.orderCount,
                    totalSpend: c.totalSpend,
                  });

                  return (
