"use client";

import { useState, useTransition } from "react";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { Plus, Trash2, Tag, Users } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent } from "@/components/ui/card";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

import { CreateTagAction, DeleteTagAction } from "@/actions/crm/customer-tags.actions";
import { cn } from "@/lib/utils";
import { tdir, tr, trv } from "@/lib/i18n/dashboard";

type TagItem = {
  id: string;
  name: string;
  color: string | null;
  createdAt: Date;
  _count: { assignments: number };
};

const PRESET_COLORS = [
  "#3B82F6", "#10B981", "#F59E0B", "#EF4444",
  "#8B5CF6", "#EC4899", "#06B6D4", "#6B7280",
  "#F97316", "#14B8A6", "#A855F7", "#0EA5E9",
];

export function TagsClient({ tags }: { tags: TagItem[] }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [name, setName] = useState("");
  const [color, setColor] = useState(PRESET_COLORS[0]);

  const handleCreate = () => {
    if (!name.trim()) { toast.error(tr("اسم العلامة مطلوب")); return; }
    startTransition(async () => {
      const res = await CreateTagAction(name.trim(), color);
      if (res.success) {
        toast.success(tr("تم إنشاء العلامة"));
        setName("");
        setColor(PRESET_COLORS[0]);
        router.refresh();
      } else {
        toast.error(trv(res.message));
      }
    });
  };

  const handleDelete = (id: string) => {
    startTransition(async () => {
      const res = await DeleteTagAction(id);
      if (res.success) { toast.success(tr("تم حذف العلامة")); router.refresh(); }
      else toast.error(trv(res.message));
    });
  };

  return (
    <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
      {/* Create form */}
      <Card className="p-5 lg:col-span-1 h-fit">
        <h2 className="mb-4 text-sm font-semibold">{tr("إنشاء علامة جديدة")}</h2>
        <div className="space-y-3">
          <div className="space-y-1.5">
            <Label>{tr("اسم العلامة *")}</Label>
            <Input
              placeholder={tr("مثال: VIP، عميل جملة")}
              value={name}
              onChange={(e) => setName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleCreate()}
            />
          </div>
          <div className="space-y-1.5">
            <Label>{tr("اللون")}</Label>
            <div className="flex flex-wrap gap-2">
              {PRESET_COLORS.map((c) => (
                <button
                  key={c}
                  type="button"
                  onClick={() => setColor(c)}
                  className={cn(
                    "size-7 rounded-full border-2 transition-all",
                    color === c ? "border-foreground scale-110" : "border-transparent hover:scale-105"
                  )}
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
            {/* Preview */}
            {name && (
              <div className="mt-2">
                <span
                  className="inline-flex rounded-full px-2.5 py-0.5 text-xs font-medium"
                  style={{ backgroundColor: `${color}20`, color }}
                >
                  {name}
                </span>
              </div>
            )}
          </div>
