"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  AlertCircle,
  Clock,
  RefreshCw,
  Unlink,
  Camera,
  Wifi,
  WifiOff,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { cn } from "@/lib/utils";
import {
  DisconnectInstagramAction,
  SyncInstagramConversationsAction,
} from "@/actions/instagram/instagram.actions";
import { toast } from "sonner";
import { tdir, tr } from "@/lib/i18n/dashboard";

type Props = {
  connection: {
    igUsername: string;
    igPageName: string | null;
    status: string;
    webhookVerified: boolean;
    lastSyncAt: Date | null;
    tokenExpiresAt: Date | null;
  };
};

export function ConnectionStatus({ connection }: Props) {
  const router = useRouter();
  const [isSyncing, startSync] = useTransition();
  const [isDisconnecting, startDisconnect] = useTransition();

  const isExpired = connection.status === "EXPIRED";
  const isActive  = connection.status === "ACTIVE";

  function handleSync() {
    startSync(async () => {
      const result = await SyncInstagramConversationsAction();
      if (result.success) {
        toast.success(tr("تم مزامنة {0} محادثة", result.synced));
        router.refresh();
      } else {
        toast.error(result.error ?? tr("فشلت المزامنة"));
      }
    });
  }

  function handleDisconnect() {
    startDisconnect(async () => {
      const result = await DisconnectInstagramAction();
      if (result.success) {
        toast.success(tr("تم قطع الاتصال بانستجرام"));
        router.refresh();
      } else {
        toast.error(result.error ?? tr("فشل قطع الاتصال"));
      }
    });
  }

  function formatLastSync(date: Date | null) {
    if (!date) return tr("لم تتم مزامنة بعد");
    const diff    = Date.now() - new Date(date).getTime();
    const minutes = Math.floor(diff / 60000);
    const hours   = Math.floor(diff / 3600000);
    const days    = Math.floor(diff / 86400000);
    if (minutes < 1)  return tr("منذ لحظات");
    if (minutes < 60) return tr("منذ {0} دقيقة", minutes);
    if (hours < 24)   return tr("منذ {0} ساعة", hours);
    return tr("منذ {0} يوم", days);
  }

  return (
    <Card
      className={cn(
        "border",
        isExpired
          ? "border-rose-500/30 bg-rose-500/5"
          : "border-emerald-500/30 bg-emerald-500/5",
      )}
    >
      <CardContent className="p-5">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-center gap-3">
            <div
              className={cn(
                "grid size-10 shrink-0 place-items-center rounded-xl",
                isActive
                  ? "bg-emerald-500/10 text-emerald-600"
                  : "bg-rose-500/10 text-rose-600",
              )}
            >
              <Camera className="size-5" />
            </div>

            <div>
              <div className="flex items-center gap-2">
                <p className="font-semibold">@{connection.igUsername}</p>
                <Badge
                  className={cn(
                    "rounded-full border-0 text-xs",
                    isActive
                      ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400"
                      : "bg-rose-500/10 text-rose-700 dark:text-rose-400",
                  )}
                >
                  {isActive ? tr("متصل") : tr("انتهت الصلاحية")}
                </Badge>
              </div>

              <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
                {connection.igPageName && (
                  <span>{tr("صفحة: {0}", connection.igPageName)}</span>
                )}
                <span className="flex items-center gap-1">
                  {connection.webhookVerified ? (
                    <Wifi className="size-3 text-emerald-500" />
                  ) : (
                    <WifiOff className="size-3 text-amber-500" />
                  )}
                  {connection.webhookVerified ? tr("Webhook مفعّل") : tr("Webhook غير مفعّل")}
                </span>
                <span className="flex items-center gap-1">
                  <Clock className="size-3" />
                  {tr("آخر مزامنة: {0}", formatLastSync(connection.lastSyncAt))}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {isActive && (
              <Button
                variant="outline"
                size="sm"
                className="rounded-xl"
                onClick={handleSync}
                disabled={isSyncing}
              >
                <RefreshCw className={cn("ms-1.5 size-4", isSyncing && "animate-spin")} />
                {isSyncing ? tr("جاري المزامنة...") : tr("مزامنة الآن")}
              </Button>
            )}

            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  className="rounded-xl text-rose-500 hover:bg-rose-500/10 hover:text-rose-600"
                  disabled={isDisconnecting}
                >
                  <Unlink className="ms-1.5 size-4" />
                  {tr("قطع الاتصال")}
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent dir={tdir()}>
                <AlertDialogHeader>
                  <AlertDialogTitle>{tr("قطع الاتصال بانستجرام؟")}</AlertDialogTitle>
                  <AlertDialogDescription>
                    {tr("سيتم حذف جميع المحادثات المحفوظة. الطلبات المقترحة ستبقى في سجلك. لا يمكن التراجع عن هذا الإجراء.")}
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel>{tr("إلغاء")}</AlertDialogCancel>
                  <AlertDialogAction
                    className="bg-rose-600 hover:bg-rose-700"
                    onClick={handleDisconnect}
                  >
                    {tr("قطع الاتصال")}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </div>
        </div>

        {isExpired && (
          <div className="mt-3 flex items-center gap-2 rounded-xl bg-rose-500/10 px-3 py-2.5 text-sm text-rose-700 dark:text-rose-400">
            <AlertCircle className="size-4 shrink-0" />
            {tr("انتهت صلاحية الربط مع انستجرام — يرجى قطع الاتصال وإعادة الربط")}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { AlertTriangle, CircleCheck, Loader2, Pause, Play, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { StatusPill } from "@/components/saas-page";
import { cn } from "@/lib/utils";
import { entityPercent, overallPercent, totalFailed, totalRemaining } from "@/lib/integrations/import/progress";
import type { JobView } from "@/lib/integrations/import/views";
import { ENTITY_META, JOB_STATUS_META, nf } from "./import-meta";
import { tdir, tr, trv } from "@/lib/i18n/dashboard";

export function Bar({ value, tone = "primary" }: { value: number; tone?: "primary" | "warning" | "success" }) {
  return (
    <div className="h-1.5 w-full overflow-hidden rounded-full bg-muted" role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100}>
      <div
        className={cn(
          "h-full rounded-full transition-[width] duration-500",
          tone === "warning" ? "bg-amber-500" : tone === "success" ? "bg-emerald-500" : "bg-primary",
        )}
        style={{ width: `${value}%` }}
      />
    </div>
  );
}

type Props = {
  job: JobView;
  onResume: () => void;
  onCancel: () => void;
  busy: boolean;
  /** Paused because the Shopify connection must be renewed (resume is disabled). */
  needsReconnect: boolean;
};

export function ProgressPanel({ job, onResume, onCancel, busy, needsReconnect }: Props) {
  const paused = job.status === "PAUSED";
  const percent = overallPercent(job.progress);
  const failed = totalFailed(job.progress);
  const remaining = totalRemaining(job.progress);
  const status = JOB_STATUS_META[job.status];

  return (
    <section className="space-y-5 rounded-xl border border-border bg-card p-5" aria-live="polite">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <h2 className="text-base font-semibold">
              {paused ? tr("الاستيراد متوقف") : job.kind === "RETRY" ? tr("بنعيد محاولة العناصر الفاشلة…") : tr("بننقل بيانات متجرك من Shopify…")}
            </h2>
            {status && <StatusPill tone={status.tone}>{status.label}</StatusPill>}
          </div>
          <p className="text-sm text-muted-foreground">
            {paused
              ? tr("كل اللي اتنقل محفوظ. لما تستكمل هنكمل من نفس المكان من غير تكرار.")
              : tr("تقدر تقفل الصفحة دي — الاستيراد شغال في الخلفية وهيوصلك إشعار لما يخلص.")}
          </p>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {paused && !needsReconnect && (
            <Button size="sm" onClick={onResume} disabled={busy}>
              {busy ? <Loader2 className="size-4 animate-spin" /> : <Play className="size-4" />}
              {tr("استكمل الاستيراد")}
            </Button>
          )}
          <AlertDialog>
            <AlertDialogTrigger asChild>
              <Button size="sm" variant="outline" disabled={busy}>
                <X className="size-4" />
                {tr("إلغاء")}
              </Button>
            </AlertDialogTrigger>
            <AlertDialogContent dir={tdir()}>
              <AlertDialogHeader>
                <AlertDialogTitle>{tr("إلغاء الاستيراد؟")}</AlertDialogTitle>
                <AlertDialogDescription>
                  {tr("البيانات اللي اتنقلت لحد دلوقتي هتفضل في متجرك. تقدر تبدأ استيراد جديد بعدين ومش هيتكرر اللي اتنقل.")}
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>{tr("كمّل الاستيراد")}</AlertDialogCancel>
                <AlertDialogAction className="bg-rose-600 hover:bg-rose-700" onClick={onCancel}>
                  {tr("إلغاء الاستيراد")}
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </div>
      </div>

      {job.lastError && (
        <p
          className={cn(
            "flex items-start gap-2 rounded-lg px-3 py-2.5 text-sm",
            paused ? "bg-amber-500/10 text-amber-800 dark:text-amber-300" : "bg-sky-500/10 text-sky-800 dark:text-sky-300",
          )}
        >
          {paused ? <Pause className="mt-0.5 size-4 shrink-0" /> : <Loader2 className="mt-0.5 size-4 shrink-0 animate-spin" />}
          <span>
            {job.lastError}
            {!paused && tr(" — بنعيد المحاولة تلقائياً.")}
          </span>
        </p>
      )}

      <div className="space-y-2">
        <div className="flex items-baseline justify-between text-sm">
          <span className="font-medium">{tr("الإجمالي")}</span>
          <span className="text-2xl font-bold tabular-nums">{tr("{0}٪", nf.format(percent))}</span>
        </div>
        <Bar value={percent} tone={paused ? "warning" : "primary"} />
        <p className="flex flex-wrap gap-x-4 text-xs text-muted-foreground">
          {remaining > 0 && <span>{tr("متبقي تقريباً {0} عنصر", nf.format(remaining))}</span>}
          {failed > 0 && <span className="text-amber-700 dark:text-amber-400">{tr("{0} عنصر فشل لحد دلوقتي", nf.format(failed))}</span>}
        </p>
      </div>

      <ul className="divide-y divide-border rounded-lg border border-border">
        {job.entities.map((entity) => {
          const p = job.progress[entity];
          if (!p) return null;
          const meta = ENTITY_META[entity];
          const pct = entityPercent(p);
          const active = job.currentEntity === entity && !paused;
          return (
            <li key={entity} className="space-y-2 px-3 py-3">
              <div className="flex items-center justify-between gap-2 text-sm">
                <span className="flex items-center gap-2 font-medium">
                  {p.done ? (
                    <CircleCheck className="size-4 text-emerald-600" />
                  ) : active ? (
                    <Loader2 className="size-4 animate-spin text-primary" />
                  ) : (
                    <span className="size-4 rounded-full border border-border" aria-hidden />
                  )}
                  {meta.label}
                </span>
                <span className="text-xs tabular-nums text-muted-foreground">
                  {nf.format(p.processed)}
                  {p.total !== null && ` / ${nf.format(p.total)}`}
                  {p.failed > 0 && (
                    <span className="ms-2 inline-flex items-center gap-1 text-amber-700 dark:text-amber-400">
                      <AlertTriangle className="size-3" />
                      {nf.format(p.failed)}
                    </span>
                  )}
                </span>
              </div>
              <Bar value={pct} tone={p.done ? "success" : "primary"} />
            </li>
          );
        })}
      </ul>
    </section>
  );
}

import type { Metadata } from "next";
import { PageHeader, readParam, type SearchParamsRecord } from "@/components/saas-page";
import { GetShopifyImportStateAction } from "@/actions/integrations/shopify-import.actions";
import { ImportHistory } from "./_components/ImportHistory";
import { ShopifyImportClient } from "./_components/ShopifyImportClient";
import { tdir, tr, trv } from "@/lib/i18n/dashboard";
import { loadDashboardLocale } from "@/lib/i18n/dashboard/server";

export async function generateMetadata(): Promise<Metadata> {
  await loadDashboardLocale();
  return {
  title: tr("استيراد من Shopify"),
};
}

export default async function ShopifyImportPage({ searchParams }: { searchParams?: Promise<SearchParamsRecord> }) {
  await loadDashboardLocale();
  const params = await searchParams;
  const state = await GetShopifyImportStateAction();

  return (
    <div className="space-y-6" dir={tdir()}>
      <PageHeader
        title={tr("استيراد من Shopify")}
        description={tr("انقل منتجاتك وعملاءك وطلباتك من Shopify لمتجرك على Kasho — من غير تكرار ومن غير ما تقعد جنب الصفحة.")}
      />

      {!state.ok ? (
        <p className="rounded-xl border border-border bg-card p-5 text-sm text-muted-foreground">{state.error}</p>
      ) : (
        <>
          <ShopifyImportClient
            configured={state.configured}
            connection={state.connection}
