  SENT: { get label() { return tr("مُرسل للمورد"); }, variant: "outline" },
  PARTIAL: { get label() { return tr("استلام جزئي"); }, variant: "default" },
  RECEIVED: { get label() { return tr("مُستلم بالكامل"); }, variant: "default" },
