                    <td className="px-4 py-3 text-center tabular-nums">{item.quantity}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={item.receivedQuantity === item.quantity ? "font-semibold text-emerald-600" : "tabular-nums"}>
