import { useState, useTransition } from "react";
import {
  Copy,
  Check,
  Sparkles,
  Loader2,
  Hash,
  Zap,
  FileText,
  Lightbulb,
  Target,
  ChevronRight,
  ArrowRight,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
