          <div className="h-6 w-6 shrink-0 animate-pulse rounded-full bg-muted" />
          <div className="flex-1 space-y-2">
            <div className="h-3 w-3/4 animate-pulse rounded bg-muted" />
            <div className="h-3 w-1/2 animate-pulse rounded bg-muted" />
          </div>
        </div>
      ))}
    </div>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

export default function MarketingAssistantModal({
  productData,
  open,
  onDone,
}: Props) {
  const [content, setContent]           = useState<MarketingContent | null>(null);
  const [error, setError]               = useState<string | null>(null);
  const [hasGenerated, setHasGenerated] = useState(false);
  const [isPending, startTransition]    = useTransition();

  function handleGenerate() {
    setError(null);
    startTransition(async () => {
      const result = await generateMarketingFromDataAction({
        title:         productData.name,
        description:   productData.description,
        pricePiasters: productData.pricePiasters,
        categoryName:  productData.categoryName,
      });

      if (result.ok) {
        setContent(result.content);
        setHasGenerated(true);
      } else {
        setError(result.error);
      }
    });
  }

  // ── Gate screen — shown before generation starts ────────────────────────────
  if (!hasGenerated && !isPending) {
    return (
      <Dialog open={open} onOpenChange={(o) => { if (!o) onDone(); }}>
        <DialogContent
          className="max-w-md rounded-2xl"
          dir={tdir()}
          aria-describedby="marketing-gate-desc"
        >
          <DialogHeader className="text-center">
            <div className="mx-auto mb-3 flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-purple-500 to-pink-500 shadow-lg">
              <Sparkles className="size-7 text-white" />
            </div>
            <DialogTitle className="text-lg">
              {tr("عزّز مبيعاتك بالذكاء الاصطناعي ✨")}
            </DialogTitle>
            <DialogDescription id="marketing-gate-desc" className="leading-6">
              {tr("احصل على")}{" "}
              <span className="font-semibold text-foreground">{tr("هوكس فايرل")}</span>{tr("، كابشن سوشيال ميديا، هاشتاجات، أفكار فيديو، وزوايا إعلانية — كلها مولّدة بالـ AI وجاهزة للنشر الآن.")}
            </DialogDescription>
          </DialogHeader>

          <div className="mt-1 rounded-xl border border-border/60 bg-muted/30 p-3.5 text-sm">
            <p className="font-medium text-foreground">{productData.name}</p>
            <p className="mt-0.5 text-muted-foreground">{productData.categoryName}</p>
          </div>

          {error && (
            <p className="rounded-xl bg-destructive/10 p-3 text-center text-sm text-destructive">
              {error}
            </p>
          )}

          <div className="grid gap-2">
            <Button
              className="w-full rounded-xl bg-gradient-to-r from-purple-600 to-pink-600 text-white hover:from-purple-700 hover:to-pink-700"
              onClick={handleGenerate}
            >
              <Sparkles className="me-2 size-4" />
              {tr("ولّد المحتوى التسويقي")}
            </Button>
            <Button
              variant="ghost"
              className="w-full rounded-xl text-muted-foreground"
              onClick={onDone}
            >
              {tr("الآن لا، أكمل")}
              <ChevronRight className="ms-1.5 size-4 ltr:-scale-x-100" />
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  // ── Loading screen ──────────────────────────────────────────────────────────
  if (isPending) {
    return (
      <Dialog open={open}>
        <DialogContent
          className="max-w-md rounded-2xl"
          dir={tdir()}
          aria-describedby="marketing-loading-desc"
        >
          <div className="flex flex-col items-center gap-5 py-8 text-center">
            <div className="relative">
              <div className="h-16 w-16 animate-spin rounded-full border-4 border-purple-500/20 border-t-purple-500" />
              <Sparkles className="absolute inset-0 m-auto size-7 text-purple-500" />
            </div>
            <div>
              <p className="text-base font-semibold" id="marketing-loading-desc">
                {tr("جاري توليد المحتوى…")}
              </p>
              <p className="mt-1 text-sm text-muted-foreground">
                {tr("الذكاء الاصطناعي يحلل منتجك ويكتب لك محتوى viral ✨")}
              </p>
            </div>
            <div className="w-full space-y-2">
              <SkeletonContent />
            </div>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  // ── Results screen ──────────────────────────────────────────────────────────
  const tabData: Record<TabId, string[]> = {
    hooks:    content?.hooks        ?? [],
    captions: content?.captions     ?? [],
    hashtags: content?.hashtags     ?? [],
    ideas:    content?.contentIdeas ?? [],
    angles:   content?.adAngles     ?? [],
  };

  function copyAll(items: string[]) {
    navigator.clipboard.writeText(items.join("\n\n"));
  }

  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o) onDone(); }}>
      <DialogContent
        className="flex max-h-[90dvh] max-w-2xl flex-col gap-0 rounded-2xl p-0"
        dir={tdir()}
        aria-describedby="marketing-results-desc"
      >
        {/* Header */}
        <div className="flex items-start justify-between border-b px-5 py-4">
          <div className="flex items-center gap-3">
            <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-purple-500 to-pink-500">
              <Sparkles className="size-4.5 text-white" />
            </div>
            <div>
              <h2 className="text-sm font-semibold leading-none">
                {tr("محتوى تسويقي لـ «{0}»", productData.name)}
              </h2>
              <p className="mt-1 text-xs text-muted-foreground" id="marketing-results-desc">
                {productData.categoryName}
              </p>
            </div>
          </div>
          <Badge
            variant="outline"
            className="shrink-0 border-purple-500/30 bg-purple-500/5 text-purple-600"
          >
            <Sparkles className="me-1 size-3" /> AI Generated
          </Badge>
        </div>

        {/* Tabs */}
        <Tabs defaultValue="hooks" className="flex min-h-0 flex-1 flex-col">
          <div className="border-b px-5 pt-3">
            <TabsList className="h-auto gap-1 bg-transparent p-0">
              {TABS.map(({ id, label, icon: Icon }) => (
                <TabsTrigger
                  key={id}
                  value={id}
                  className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground"
                >
                  <Icon className="size-3" />
                  {label}
                  {tabData[id].length > 0 && (
                    <span className="ms-0.5 rounded-full bg-current/15 px-1 text-[10px] font-bold">
                      {tabData[id].length}
                    </span>
                  )}
                </TabsTrigger>
              ))}
            </TabsList>
          </div>

          {TABS.map(({ id }) => (
            <TabsContent key={id} value={id} className="mt-0 flex-1 overflow-hidden">
              <div className="h-85 overflow-y-auto">
                <div className="p-4">
                  {id === "hashtags" ? (
                    <div className="flex flex-wrap gap-2">
                      {tabData[id].map((tag, i) => (
                        <HashtagPill key={i} tag={tag} />
                      ))}
                    </div>
                  ) : (
                    <div className="space-y-2.5">
                      {tabData[id].map((item, i) => (
                        <ContentCard key={i} text={item} index={i} />
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </TabsContent>
          ))}
        </Tabs>

        {/* Footer actions */}
        <div className="flex items-center justify-between border-t px-5 py-3">
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              className="rounded-lg text-xs"
              onClick={handleGenerate}
              disabled={isPending}
            >
              <Sparkles className="me-1.5 size-3" />
              {tr("أعد التوليد")}
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="rounded-lg text-xs text-muted-foreground"
              onClick={() => copyAll(
                Object.values(tabData).flat(),
              )}
            >
              <Copy className="me-1.5 size-3" />
              {tr("نسخ الكل")}
            </Button>
          </div>
          <Button
            size="sm"
            className="rounded-lg text-xs"
            onClick={onDone}
          >
            {tr("انتهيت")}
            <ArrowRight className="ms-1.5 size-3 ltr:-scale-x-100" />
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { Plus, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { tr } from "@/lib/i18n/dashboard";

export type WholesaleTier = {
  minQty: number;
  maxQty?: number;
  price: number;
};

type Props = {
  initialTiers?: WholesaleTier[];
};

export default function WholesaleInput({ initialTiers = [] }: Props) {
  const [enabled, setEnabled] = useState(initialTiers.length > 0);
  const [tiers, setTiers] = useState<WholesaleTier[]>(
    initialTiers.length > 0
      ? initialTiers
      : [{ minQty: 10, price: 0 }],
  );

  function addTier() {
    const lastTier = tiers[tiers.length - 1];
    const nextMin = lastTier ? (lastTier.maxQty ? lastTier.maxQty + 1 : lastTier.minQty + 10) : 10;
    setTiers((prev) => [...prev, { minQty: nextMin, price: 0 }]);
  }

  function removeTier(index: number) {
    setTiers((prev) => prev.filter((_, i) => i !== index));
  }

  function updateTier(index: number, field: keyof WholesaleTier, value: string) {
    setTiers((prev) =>
      prev.map((tier, i) => {
        if (i !== index) return tier;
        const num = Number(value);
        if (field === "maxQty") {
          return { ...tier, maxQty: value === "" ? undefined : isNaN(num) ? undefined : num };
        }
        return { ...tier, [field]: isNaN(num) ? 0 : num };
      }),
    );
  }

  const serialized = enabled && tiers.length > 0 ? JSON.stringify(tiers) : "[]";

  return (
    <div className="space-y-4">
      <label className="flex cursor-pointer items-center gap-3">
        <div
          role="checkbox"
          aria-checked={enabled}
          tabIndex={0}
          onClick={() => setEnabled((v) => !v)}
          onKeyDown={(e) => e.key === " " && setEnabled((v) => !v)}
          className={`relative h-5 w-9 rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
            enabled ? "bg-primary" : "bg-muted-foreground/30"
          }`}
        >
          <span
            className={`absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform ${
              enabled ? "translate-x-4 rtl:-translate-x-4" : "translate-x-0.5 rtl:-translate-x-0.5"
            }`}
          />
        </div>
        <span className="text-sm font-medium">{tr("تفعيل أسعار الجملة")}</span>
      </label>

      {enabled && (
        <div className="space-y-3">
          <div className="grid grid-cols-[1fr_1fr_1fr_auto] gap-2 text-xs font-medium text-muted-foreground">
            <span>{tr("الحد الأدنى للكمية")}</span>
            <span>{tr("الحد الأقصى (اختياري)")}</span>
            <span>{tr("السعر للقطعة (ج.م)")}</span>
            <span />
          </div>

          {tiers.map((tier, i) => (
            <div key={i} className="grid grid-cols-[1fr_1fr_1fr_auto] items-center gap-2">
              <div className="relative">
                <Input
                  type="number"
                  min={1}
                  step={1}
                  value={tier.minQty}
                  onChange={(e) => updateTier(i, "minQty", e.target.value)}
                  placeholder="10"
                  className="rounded-xl pe-8 text-sm"
                />
                <span className="pointer-events-none absolute inset-e-2.5 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                  {tr("قطعة")}
                </span>
              </div>

              <div className="relative">
                <Input
                  type="number"
                  min={tier.minQty + 1}
                  step={1}
                  value={tier.maxQty ?? ""}
                  onChange={(e) => updateTier(i, "maxQty", e.target.value)}
                  placeholder="∞"
                  className="rounded-xl pe-8 text-sm"
                />
                <span className="pointer-events-none absolute inset-e-2.5 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                  {tr("قطعة")}
                </span>
              </div>

              <div className="relative">
                <Input
                  type="number"
                  min={0}
                  step={0.01}
                  value={tier.price || ""}
                  onChange={(e) => updateTier(i, "price", e.target.value)}
                  placeholder="0.00"
                  className="rounded-xl pe-10 text-sm"
                  required={enabled}
                />
                <span className="pointer-events-none absolute inset-e-2.5 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                  {tr("ج.م")}
                </span>
              </div>

              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="size-9 shrink-0 rounded-xl text-muted-foreground hover:text-destructive"
                onClick={() => removeTier(i)}
              >
                <Trash2 className="size-4" />
              </Button>
            </div>
          ))}

          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={addTier}
            className="w-full rounded-xl gap-1.5"
          >
            <Plus className="size-3.5" />
            {tr("إضافة شريحة سعرية")}
          </Button>

          <p className="text-xs text-muted-foreground">
            {tr("مثال: 10-49 قطعة بسعر 45 ج.م، و50+ قطعة بسعر 38 ج.م")}
          </p>
        </div>
      )}

      <input type="hidden" name="wholesaleOptions" value={serialized} />
    </div>
  );
}

import type { ReactNode } from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { tr, trv } from "@/lib/i18n/dashboard";

type FormSectionProps = {
  title: string;
  description?: string;
  /** Collapsed by default — for advanced, rarely used settings. Fields stay in the form either way. */
  collapsible?: boolean;
  aside?: ReactNode;
  children: ReactNode;
  className?: string;
};

export function FormSection({ title, description, collapsible, aside, children, className }: FormSectionProps) {
  const heading = (
    <div className="min-w-0 flex-1">
      <h2 className="text-sm font-semibold">{title}</h2>
      {description && <p className="mt-0.5 text-xs leading-5 text-muted-foreground">{description}</p>}
    </div>
  );

  if (collapsible) {
    return (
      <details className={cn("group rounded-xl border border-border bg-card", className)}>
        <summary className="flex cursor-pointer list-none items-center gap-3 px-5 py-4 [&::-webkit-details-marker]:hidden">
          {heading}
          <ChevronDown className="size-4 shrink-0 text-muted-foreground transition-transform group-open:rotate-180" />
        </summary>
        <div className="border-t border-border px-5 py-5">{children}</div>
      </details>
    );
  }

  return (
    <section className={cn("rounded-xl border border-border bg-card", className)}>
      <div className="flex items-start gap-3 px-5 pt-4 pb-3">
        {heading}
        {aside}
      </div>
      <div className="px-5 pb-5">{children}</div>
    </section>
  );
}

/** Label + control + hint/error, the one field layout for product forms. */
export function Field({
  label,
  htmlFor,
  optional,
  hint,
  error,
  children,
  className,
}: {
  label: string;
  htmlFor?: string;
  optional?: boolean;
  hint?: ReactNode;
  error?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("space-y-1.5", className)}>
      <label htmlFor={htmlFor} className="flex items-center gap-1.5 text-sm font-medium">
        {label}
        {optional && <span className="text-xs font-normal text-muted-foreground">{tr("(اختياري)")}</span>}
      </label>
      {children}
      {error ? (
        <p role="alert" className="text-xs font-medium text-destructive">
          {error}
        </p>
      ) : (
        hint && <p className="text-xs leading-5 text-muted-foreground">{hint}</p>
      )}
    </div>
  );
}

