            <DialogDescription>
              {tr("هذا إجراء لا يمكن التراجع عنه. سيصبح")}{" "}
              <strong>{transferTarget?.name ?? transferTarget?.email}</strong>{" "}{tr("المالك الجديد للمتجر، وستصبح أنت مديراً.")}
            </DialogDescription>
