              {tr("إلغاء")}
            </Button>
            <Button
              variant="destructive"
              className=""
              disabled={transferConfirmText !== "نقل الملكية" || isPending}
              onClick={handleTransferConfirm}
            >
              {isPending ? tr("جاري النقل...") : tr("تأكيد النقل")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

