import { intlLocale, tdir, tr } from "@/lib/i18n/dashboard";
import { loadDashboardLocale } from "@/lib/i18n/dashboard/server";

export async function generateMetadata(): Promise<Metadata> {
  await loadDashboardLocale();
  return {
  title: tr("الطلبات المقترحة"),
};
}

const PAGE_SIZE = 10;

const STATUS_LABELS: Record<SuggestedOrderStatus, string> = {
  get PENDING() { return tr("قيد المراجعة"); },
  get APPROVED() { return tr("معتمد"); },
  get REJECTED() { return tr("مرفوض"); },
  get EXPIRED() { return tr("منتهي الصلاحية"); },
};

const STATUS_CLASSES: Record<SuggestedOrderStatus, string> = {
  PENDING: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  APPROVED: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400",
  REJECTED: "bg-rose-500/10 text-rose-700 dark:text-rose-400",
  EXPIRED: "bg-zinc-500/10 text-zinc-600 dark:text-zinc-400",
};

function formatDate(date: Date) {
  return new Intl.DateTimeFormat(intlLocale(), {
    day: "numeric",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(date));
}

type Props = {
  searchParams?: Promise<{ page?: string; status?: string }>;
};

export default async function SuggestedOrdersPage({ searchParams }: Props) {
  await loadDashboardLocale();
  const resolved = await searchParams;
  const currentPage = Math.max(1, Number(resolved?.page) || 1);
  const statusFilter = resolved?.status as SuggestedOrderStatus | undefined;

  const { orders, total, totalPages } = await GetSuggestedOrdersAction({
    page: currentPage,
    status: statusFilter,
  });

  const tabs: Array<{ label: string; value?: SuggestedOrderStatus }> = [
    { label: tr("الكل") },
    { label: tr("قيد المراجعة"), value: "PENDING" },
    { label: tr("معتمد"), value: "APPROVED" },
    { label: tr("مرفوض"), value: "REJECTED" },
  ];

  return (
    <div className="space-y-6" dir={tdir()}>
      <DashboardSectionHeader
        icon={Sparkles}
        badge={total}
        title={tr("الطلبات المقترحة من انستجرام")}
        description={tr("طلبات اكتشفها الذكاء الاصطناعي من محادثاتك — راجعها واعتمدها")}
        actionLabel={tr("إعدادات الربط")}
        actionHref="/dashboard/integrations/instagram"
      />

      {/* Status filter tabs */}
      <div className="flex flex-wrap gap-2">
        {tabs.map((tab) => {
          const isActive =
            statusFilter === tab.value || (!statusFilter && !tab.value);
          const href = tab.value
            ? `/dashboard/suggested-orders?status=${tab.value}`
            : "/dashboard/suggested-orders";

          return (
            <Link key={tab.label} href={href}>
              <Badge
                variant={isActive ? "default" : "outline"}
                className={cn(
                  "cursor-pointer rounded-full px-3 py-1 text-xs transition-colors",
                  !isActive && "hover:bg-muted",
                )}
              >
                {tab.label}
              </Badge>
            </Link>
          );
        })}
      </div>

      {orders.length === 0 ? (
        <Card className="border-dashed border-border/40">
          <CardContent className="flex min-h-72 flex-col items-center justify-center text-center">
            <div className="mb-4 grid size-16 place-items-center rounded-2xl bg-muted text-muted-foreground">
              <FolderOpen className="size-7" />
            </div>
            <h2 className="text-xl font-bold">{tr("لا توجد طلبات مقترحة")}</h2>
            <p className="mt-2 max-w-md text-sm leading-6 text-muted-foreground">
              {statusFilter
                ? tr("لا توجد طلبات بهذه الحالة حالياً")
                : tr("لما يكتشف الذكاء الاصطناعي طلبات من محادثاتك ستظهر هنا للمراجعة")}
            </p>
            {!statusFilter && (
              <Button asChild variant="outline" className="mt-4 rounded-xl">
                <Link href="/instagram">{tr("ربط انستجرام")}</Link>
              </Button>
            )}
          </CardContent>
        </Card>
      ) : (
        <>
          <Card className="border-border shadow-sm">
            <CardContent className="divide-y divide-border/30 p-0">
              {orders.map((order) => (
                <div
                  key={order.id}
                  className="flex flex-col gap-3 p-4 transition-colors hover:bg-muted/20 sm:flex-row sm:items-center sm:justify-between"
                >
                  <div className="flex items-start gap-3">
                    <div className="mt-0.5 grid size-9 shrink-0 place-items-center rounded-xl bg-muted">
                      <Sparkles className="size-4 text-amber-500" />
                    </div>

                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <ConfidenceBadge confidence={order.confidence} size="sm" />
                        <Badge
                          className={cn(
                            "rounded-full border-0 text-xs",
                            STATUS_CLASSES[order.status],
                          )}
                        >
                          {STATUS_LABELS[order.status]}
                        </Badge>
                      </div>

                      <div className="mt-1.5 flex flex-wrap items-center gap-x-3 gap-y-1 text-sm">
                        {order.customerName && (
                          <span className="flex items-center gap-1 font-medium">
                            <User className="size-3.5 text-muted-foreground" />
                            {order.customerName}
                          </span>
                        )}
                        {order.customerPhone && (
                          <span className="flex items-center gap-1 text-muted-foreground">
                            <Phone className="size-3.5" />
                            {order.customerPhone}
                          </span>
                        )}
                        {order.firstProductName && (
                          <span className="flex items-center gap-1 text-muted-foreground">
                            <Package className="size-3.5" />
                            {order.firstProductName}
                            {order.itemCount > 1 && ` +${order.itemCount - 1}`}
                          </span>
                        )}
                      </div>

                      <p className="mt-1 text-xs text-muted-foreground">
                        {formatDate(order.createdAt)}
                      </p>
                    </div>
                  </div>

                  <div className="flex shrink-0 items-center gap-2 sm:ps-4">
                    {order.status === "PENDING" && (
                      <RejectDialog suggestedOrderId={order.id} />
                    )}
                    <Button
                      asChild
                      variant={order.status === "PENDING" ? "default" : "outline"}
                      size="sm"
                      className="rounded-xl"
                    >
                      <Link href={`/dashboard/suggested-orders/${order.id}`}>
                        <Eye className="ms-1.5 size-4" />
                        {order.status === "PENDING" ? tr("مراجعة") : tr("عرض")}
                      </Link>
                    </Button>
                  </div>
                </div>
              ))}
            </CardContent>
          </Card>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex flex-col items-center justify-between gap-4 rounded-2xl border border-border/30 bg-background px-5 py-4 sm:flex-row">
              <p className="text-sm text-muted-foreground">
                {tr("الصفحة")}{" "}
                <span className="font-bold text-foreground">{currentPage}</span>{" "}{tr("من")}{" "}
                <span className="font-bold text-foreground">{totalPages}</span>
              </p>
              <div className="flex items-center gap-2">
                <Button
                  asChild
                  variant="outline"
                  size="sm"
                  disabled={currentPage <= 1}
                  className="rounded-xl"
                >
                  <Link
                    href={
                      currentPage > 1
                        ? `/dashboard/suggested-orders?page=${currentPage - 1}${statusFilter ? `&status=${statusFilter}` : ""}`
                        : "#"
                    }
                  >
                    <ChevronRight className="me-1 size-4 ltr:-scale-x-100" />
                    {tr("السابق")}
                  </Link>
                </Button>
                <Button
                  asChild
                  variant="outline"
                  size="sm"
                  disabled={currentPage >= totalPages}
                  className="rounded-xl"
                >
                  <Link
                    href={
                      currentPage < totalPages
                        ? `/dashboard/suggested-orders?page=${currentPage + 1}${statusFilter ? `&status=${statusFilter}` : ""}`
                        : "#"
                    }
                  >
                    {tr("التالي")}
                    <ChevronLeft className="ms-1 size-4 ltr:-scale-x-100" />
                  </Link>
                </Button>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import {
  CheckCircle2,
  ChevronLeft,
  Loader2,
  Package,
  Settings2,
  Sparkles,
  Store,
  Zap,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { CompleteOnboardingAction } from "@/actions/onboarding/onboarding.actions";
import { toast } from "sonner";
import { lazyList, tdir, tr, trv } from "@/lib/i18n/dashboard";

const BUSINESS_CATEGORIES = [
  { value: "fashion", get label() { return tr("أزياء وملابس"); } },
  { value: "electronics", get label() { return tr("إلكترونيات وتقنية"); } },
  { value: "food", get label() { return tr("أغذية ومشروبات"); } },
  { value: "beauty", get label() { return tr("عناية وجمال"); } },
  { value: "home", get label() { return tr("أثاث ومنزل"); } },
  { value: "sports", get label() { return tr("رياضة ولياقة"); } },
  { value: "books", get label() { return tr("كتب وقرطاسية"); } },
  { value: "other", get label() { return tr("أخرى"); } },
];

const LANGUAGES = [
  { value: "ar", get label() { return tr("العربية"); }, flag: "🇸🇦" },
  { value: "en", label: "English", flag: "🇬🇧" },
];

const TIMEZONES = [
  { value: "Africa/Cairo", get label() { return tr("القاهرة (UTC+2)"); } },
  { value: "Asia/Riyadh", get label() { return tr("الرياض (UTC+3)"); } },
  { value: "Asia/Dubai", get label() { return tr("دبي (UTC+4)"); } },
  { value: "Asia/Kuwait", get label() { return tr("الكويت (UTC+3)"); } },
  { value: "Asia/Amman", get label() { return tr("عمّان (UTC+3)"); } },
];

const STEPS = lazyList(["بيانات النشاط", "تفضيلات المتجر", "إعداد المنتجات", "الانتهاء"] as const);

type Props = {
  storeName: string;
  businessCategory: string;
  trialEndDate: string | null;
};

export default function OnboardingWizard({ storeName, businessCategory, trialEndDate }: Props) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();

  const [step, setStep] = useState(1);

  // Step 1
  const [name, setName] = useState(storeName);
  const [category, setCategory] = useState(businessCategory);

  // Step 2
  const [language, setLanguage] = useState("ar");
  const [timezone, setTimezone] = useState("Africa/Cairo");

  // Step 3
  const [useDemoData, setUseDemoData] = useState<boolean | null>(null);

  const [isDone, setIsDone] = useState(false);

  const trialDaysLeft = trialEndDate
    ? Math.max(0, Math.ceil((new Date(trialEndDate).getTime() - Date.now()) / 86400000))
    : 3;

  function handleNext() {
    if (step === 1) {
      if (!name.trim()) {
        toast.error(tr("يرجى كتابة اسم المتجر"));
        return;
      }
      setStep(2);
      return;
    }

    if (step === 2) {
      setStep(3);
      return;
    }

    if (step === 3) {
      if (useDemoData === null) {
        toast.error(tr("يرجى اختيار طريقة الإعداد"));
        return;
      }
      startTransition(async () => {
        const result = await CompleteOnboardingAction({
          storeName: name,
          businessCategory: category,
          language,
          useDemoData: useDemoData === true,
        });
        if (result.success) {
          setStep(4);
          setIsDone(true);
          setTimeout(() => router.push("/dashboard"), 2500);
        } else {
          toast.error(trv(result.message));
        }
      });
    }
  }

  function handleBack() {
    if (step > 1) setStep((s) => s - 1);
  }

  const totalSteps = STEPS.length;

  return (
    <div dir={tdir()} className="flex min-h-screen flex-col bg-background">
      {/* Header */}
      <header className="flex h-14 items-center border-b px-6">
        <Image src="/logo.svg" alt={tr("كاشو")} width={32} height={32} className="rounded-lg" />
        <span className="ms-2 font-bold text-foreground">{tr("كاشو")}</span>
        <span className="ms-3 rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-medium text-amber-700 dark:bg-amber-900/30 dark:text-amber-400">
          {trialDaysLeft} {trialDaysLeft === 1 ? tr("يوم") : tr("أيام")}{" "}{tr("تجريبية")}
        </span>
      </header>

      {/* Progress bar */}
      <div className="h-1 bg-border">
        <div
          className="h-full bg-primary transition-all duration-500"
          style={{ width: `${(step / totalSteps) * 100}%` }}
        />
      </div>

      <main className="mx-auto flex w-full max-w-lg flex-1 flex-col justify-center px-6 py-12">
        {/* Step indicators */}
        <div className="mb-10 flex items-center justify-center gap-1.5 overflow-x-auto">
          {STEPS.map((label, i) => {
            const n = i + 1;
            const done = step > n;
            const active = step === n;
            return (
              <div key={n} className="flex items-center gap-1.5">
                <div
                  className={cn(
                    "flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-xs font-bold transition-all",
                    done
                      ? "bg-primary text-primary-foreground"
                      : active
                        ? "border-2 border-primary bg-primary/10 text-primary"
                        : "border-2 border-border text-muted-foreground"
                  )}
                >
                  {done ? <CheckCircle2 className="h-4 w-4" /> : n}
                </div>
                <span
                  className={cn(
                    "hidden text-xs sm:inline",
                    active ? "font-semibold text-foreground" : "text-muted-foreground"
                  )}
                >
                  {label}
                </span>
                {i < STEPS.length - 1 && (
                  <div className={cn("mx-1 h-px w-6 shrink-0", step > n ? "bg-primary" : "bg-border")} />
                )}
              </div>
            );
          })}
        </div>

        {/* ── Step 1: Business Info ── */}
        {step === 1 && (
          <div className="space-y-6">
            <div>
              <div className="mb-1 flex items-center gap-2 text-primary">
                <Store className="h-5 w-5" />
                <span className="text-sm font-medium">{tr("الخطوة ١ من {0}", totalSteps)}</span>
              </div>
              <h1 className="text-2xl font-bold">{tr("بيانات نشاطك التجاري")}</h1>
              <p className="mt-1 text-sm text-muted-foreground">
                {tr("أخبرنا عن متجرك لنساعدك على البدء بأفضل إعداد")}
              </p>
            </div>

            <div className="space-y-2">
              <label htmlFor="storeName" className="text-sm font-medium">
                {tr("اسم المتجر")}
              </label>
              <Input
                id="storeName"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder={tr("مثال: Maro Store")}
                className="h-11"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">{tr("نوع النشاط التجاري")}</label>
              <div className="grid grid-cols-2 gap-2">
                {BUSINESS_CATEGORIES.map((cat) => (
                  <button
                    key={cat.value}
                    type="button"
                    onClick={() => setCategory(cat.value)}
                    className={cn(
                      "rounded-xl border px-3 py-2.5 text-start text-sm transition-all",
                      category === cat.value
                        ? "border-primary bg-primary/5 font-semibold text-primary"
                        : "border-border hover:border-primary/40 hover:bg-muted/50"
                    )}
                  >
                    {cat.label}
                  </button>
                ))}
              </div>
            </div>

            <Button className="w-full" size="lg" onClick={handleNext} disabled={!name.trim()}>
              {tr("التالي")}
              <ChevronLeft className="ms-2 h-4 w-4 ltr:-scale-x-100" />
            </Button>
          </div>
        )}

        {/* ── Step 2: Preferences ── */}
        {step === 2 && (
          <div className="space-y-6">
            <div>
              <div className="mb-1 flex items-center gap-2 text-primary">
                <Settings2 className="h-5 w-5" />
                <span className="text-sm font-medium">{tr("الخطوة ٢ من {0}", totalSteps)}</span>
              </div>
              <h1 className="text-2xl font-bold">{tr("تفضيلات المتجر")}</h1>
              <p className="mt-1 text-sm text-muted-foreground">
                {tr("اضبط الإعدادات الأساسية لمتجرك")}
              </p>
            </div>

            {/* Currency - display only */}
            <div className="rounded-xl border bg-muted/30 p-4">
              <p className="mb-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                {tr("العملة")}
              </p>
              <div className="flex items-center gap-2">
                <span className="text-lg font-bold">{tr("جنيه مصري")}</span>
                <span className="rounded bg-muted px-2 py-0.5 text-xs font-mono text-muted-foreground">EGP</span>
              </div>
              <p className="mt-1 text-xs text-muted-foreground">{tr("العملة الافتراضية للمنصة")}</p>
            </div>

            {/* Language */}
            <div className="space-y-2">
              <label className="text-sm font-medium">{tr("لغة المتجر")}</label>
              <div className="grid grid-cols-2 gap-2">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.value}
                    type="button"
                    onClick={() => setLanguage(lang.value)}
                    className={cn(
                      "flex items-center gap-2 rounded-xl border px-4 py-3 text-sm transition-all",
                      language === lang.value
                        ? "border-primary bg-primary/5 font-semibold text-primary"
                        : "border-border hover:border-primary/40 hover:bg-muted/50"
                    )}
                  >
                    <span className="text-xl">{lang.flag}</span>
                    {lang.label}
                    {language === lang.value && (
                      <CheckCircle2 className="ms-auto h-4 w-4 text-primary" />
                    )}
                  </button>
                ))}
              </div>
            </div>

            {/* Timezone */}
            <div className="space-y-2">
              <label className="text-sm font-medium">{tr("المنطقة الزمنية")}</label>
              <div className="space-y-1.5">
                {TIMEZONES.map((tz) => (
                  <button
                    key={tz.value}
                    type="button"
                    onClick={() => setTimezone(tz.value)}
                    className={cn(
                      "flex w-full items-center justify-between rounded-xl border px-4 py-2.5 text-sm transition-all",
                      timezone === tz.value
                        ? "border-primary bg-primary/5 font-semibold text-primary"
                        : "border-border hover:border-primary/40 hover:bg-muted/50"
                    )}
                  >
                    {tz.label}
                    {timezone === tz.value && (
                      <CheckCircle2 className="h-4 w-4 text-primary" />
                    )}
                  </button>
                ))}
              </div>
            </div>

            <div className="flex gap-3">
              <Button variant="outline" className="flex-1" onClick={handleBack}>
                {tr("رجوع")}
              </Button>
              <Button className="flex-1" size="lg" onClick={handleNext}>
                {tr("التالي")}
                <ChevronLeft className="ms-2 h-4 w-4 ltr:-scale-x-100" />
              </Button>
            </div>
          </div>
        )}

        {/* ── Step 3: Product Setup ── */}
        {step === 3 && (
          <div className="space-y-6">
            <div>
              <div className="mb-1 flex items-center gap-2 text-primary">
                <Package className="h-5 w-5" />
                <span className="text-sm font-medium">{tr("الخطوة ٣ من {0}", totalSteps)}</span>
              </div>
              <h1 className="text-2xl font-bold">{tr("إعداد المنتجات")}</h1>
              <p className="mt-1 text-sm text-muted-foreground">
                {tr("كيف تريد أن تبدأ متجرك؟")}
              </p>
            </div>

            <div className="grid gap-3">
              {/* Demo data option */}
              <button
                type="button"
                onClick={() => setUseDemoData(true)}
                className={cn(
                  "group relative rounded-2xl border-2 p-5 text-start transition-all",
                  useDemoData === true
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/40 hover:bg-muted/30"
                )}
              >
                <div className="flex items-start gap-3">
                  <div
                    className={cn(
                      "flex h-10 w-10 shrink-0 items-center justify-center rounded-xl transition-colors",
                      useDemoData === true ? "bg-primary text-primary-foreground" : "bg-muted"
                    )}
                  >
                    <Sparkles className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="font-semibold">{tr("ابدأ ببيانات تجريبية")}</p>
                    <p className="mt-0.5 text-sm text-muted-foreground">
                      {tr("سنضيف منتجات وطلبات وعملاء نموذجيين لتستكشف المنصة بسهولة")}
                    </p>
                    <div className="mt-2 flex flex-wrap gap-1.5">
                      {[tr("٥ منتجات"), tr("٣ طلبات"), tr("٣ عملاء")].map((t) => (
                        <span
                          key={t}
                          className="rounded-full bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary"
                        >
                          {t}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
                {useDemoData === true && (
                  <CheckCircle2 className="absolute end-4 top-4 h-5 w-5 text-primary" />
                )}
              </button>

              {/* Empty option */}
              <button
                type="button"
                onClick={() => setUseDemoData(false)}
                className={cn(
                  "group relative rounded-2xl border-2 p-5 text-start transition-all",
                  useDemoData === false
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/40 hover:bg-muted/30"
                )}
              >
                <div className="flex items-start gap-3">
                  <div
                    className={cn(
                      "flex h-10 w-10 shrink-0 items-center justify-center rounded-xl transition-colors",
                      useDemoData === false ? "bg-primary text-primary-foreground" : "bg-muted"
                    )}
                  >
                    <Zap className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="font-semibold">{tr("ابدأ من الصفر")}</p>
                    <p className="mt-0.5 text-sm text-muted-foreground">
                      {tr("متجر نظيف تمامًا، أضف منتجاتك وبياناتك الحقيقية بنفسك")}
                    </p>
                  </div>
                </div>
                {useDemoData === false && (
                  <CheckCircle2 className="absolute end-4 top-4 h-5 w-5 text-primary" />
                )}
              </button>
            </div>

            <div className="flex gap-3">
              <Button
                variant="outline"
                className="flex-1"
                onClick={handleBack}
                disabled={isPending}
              >
                {tr("رجوع")}
              </Button>
              <Button
                className="flex-1"
                size="lg"
                onClick={handleNext}
                disabled={useDemoData === null || isPending}
              >
                {isPending ? (
                  <>
                    <Loader2 className="me-2 h-4 w-4 animate-spin" />
                    {tr("جاري الإعداد...")}
                  </>
                ) : (
                  <>
                    {tr("إنهاء الإعداد")}
                    <ChevronLeft className="ms-2 h-4 w-4 ltr:-scale-x-100" />
                  </>
                )}
              </Button>
            </div>
          </div>
        )}

        {/* ── Step 4: Done ── */}
        {step === 4 && (
          <div className="flex flex-col items-center space-y-6 text-center">
            <div className="flex h-20 w-20 items-center justify-center rounded-full bg-primary/10">
              {isDone ? (
                <CheckCircle2 className="h-10 w-10 text-primary" />
              ) : (
                <Loader2 className="h-10 w-10 animate-spin text-primary" />
              )}
            </div>
            <div>
              <h1 className="text-2xl font-bold">{tr("متجرك جاهز! 🎉")}</h1>
              <p className="mt-2 text-muted-foreground">
                {tr("تم إعداد متجرك بنجاح، يتم تحويلك إلى لوحة التحكم الآن...")}
              </p>
            </div>
            <div className="w-full overflow-hidden rounded-full bg-border">
              <div className="h-1.5 animate-pulse rounded-full bg-primary" style={{ width: "70%" }} />
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Banknote, CreditCard, Landmark, Loader2, Plus, Smartphone, Split, Trash2, Wallet, type LucideIcon } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { egp, egpNumber } from "./pos-format";
import { tdir, tr, trv } from "@/lib/i18n/dashboard";

export type PaymentEntry = { paymentMethod: string; amount: number; reference?: string };

const METHODS: { key: string; label: string; icon: LucideIcon }[] = [
  { key: "cash", get label() { return tr("كاش"); }, icon: Banknote },
  { key: "card", get label() { return tr("فيزا / بطاقة"); }, icon: CreditCard },
  { key: "vodafone_cash", get label() { return tr("فودافون كاش"); }, icon: Smartphone },
  { key: "instapay", get label() { return tr("إنستاباي"); }, icon: Wallet },
  { key: "bank_transfer", get label() { return tr("تحويل بنكي"); }, icon: Landmark },
];

const toPiasters = (value: string) => {
  const n = Number(value);
  return value.trim() === "" || Number.isNaN(n) ? 0 : Math.round(n * 100);
};

/** Exact amount + the bills a customer is likely to hand over. */
function quickCashAmounts(total: number) {
  const pounds = total / 100;
  const options = new Set<number>([pounds]);
  for (const step of [50, 100, 200, 500]) {
    const rounded = Math.ceil(pounds / step) * step;
    if (rounded > pounds) options.add(rounded);
  }
  return [...options].slice(0, 5);
}

type Props = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Piasters. */
  total: number;
  onConfirm: (payments: PaymentEntry[]) => void;
  loading?: boolean;
};

/**
 * Collects payment. Change handed back is never recorded as revenue: cash is
 * saved as the amount due, so the shift's expected cash stays correct.
 */
export default function PaymentDialog(props: Props) {
  // Remount on every open so each sale starts clean.
  return props.open ? <PaymentDialogBody key={props.total} {...props} /> : null;
}

function PaymentDialogBody({ open, onOpenChange, total, onConfirm, loading }: Props) {
  const [split, setSplit] = useState(false);
  const [method, setMethod] = useState("cash");
  const [received, setReceived] = useState("");
  const [reference, setReference] = useState("");
  const [entries, setEntries] = useState<{ paymentMethod: string; amount: string; reference: string }[]>([
    { paymentMethod: "cash", amount: "", reference: "" },
    { paymentMethod: "card", amount: "", reference: "" },
  ]);
  const [error, setError] = useState<string>();

  // ── Single method ─────────────────────────────────────────────
  const receivedPiasters = received ? toPiasters(received) : total;
  const change = method === "cash" ? Math.max(0, receivedPiasters - total) : 0;
  const short = method === "cash" ? Math.max(0, total - receivedPiasters) : 0;

  // ── Split ─────────────────────────────────────────────────────
  const splitPaid = entries.reduce((sum, e) => sum + toPiasters(e.amount), 0);
  const splitRemaining = Math.max(0, total - splitPaid);
  const splitChange = Math.max(0, splitPaid - total);

  function confirm() {
    setError(undefined);

    if (!split) {
      if (short > 0) {
        setError(tr("ناقص {0}", egp(short)));
        return;
      }
      onConfirm([{ paymentMethod: method, amount: total, reference: reference.trim() || undefined }]);
      return;
    }

    const payments = entries
      .map((e) => ({ paymentMethod: e.paymentMethod, amount: toPiasters(e.amount), reference: e.reference.trim() || undefined }))
      .filter((p) => p.amount > 0);

    if (splitRemaining > 0) {
      setError(tr("لسه ناقص {0}", egp(splitRemaining)));
      return;
    }
    if (splitChange > 0) {
      // Extra can only be cash change — take it off a cash line.
      const cash = payments.find((p) => p.paymentMethod === "cash" && p.amount >= splitChange);
      if (!cash) {
        setError(tr("المبلغ الزيادة لازم يكون من الكاش عشان يرجع فكة."));
        return;
      }
      cash.amount -= splitChange;
    }
    onConfirm(payments.filter((p) => p.amount > 0));
  }

  const setEntry = (i: number, patch: Partial<(typeof entries)[number]>) =>
    setEntries((prev) => prev.map((e, j) => (j === i ? { ...e, ...patch } : e)));

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md gap-0 p-0" dir={tdir()}>
        <DialogHeader className="border-b border-border p-5 text-start">
          <DialogTitle>{tr("الدفع")}</DialogTitle>
          <DialogDescription className="sr-only">{tr("اختار طريقة الدفع وأكّد البيع")}</DialogDescription>
          <p className="pt-2 text-3xl font-bold tracking-tight tabular-nums">{egp(total)}</p>
        </DialogHeader>

        <form
          onSubmit={(e) => {
            e.preventDefault();
            confirm();
          }}
          className="space-y-5 p-5"
        >
          {!split ? (
            <>
              <div role="radiogroup" aria-label={tr("طريقة الدفع")} className="grid grid-cols-3 gap-2">
                {METHODS.map(({ key, label, icon: Icon }) => (
                  <button
                    key={key}
                    type="button"
                    role="radio"
                    aria-checked={method === key}
                    onClick={() => {
                      setMethod(key);
                      setError(undefined);
                    }}
                    className={cn(
                      "flex flex-col items-center gap-1.5 rounded-lg border px-2 py-3 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                      method === key ? "border-primary bg-primary/5 text-foreground" : "border-border text-muted-foreground hover:bg-muted",
                    )}
                  >
                    <Icon className={cn("size-5", method === key && "text-primary")} />
                    {label}
                  </button>
                ))}
                <button
                  type="button"
                  onClick={() => setSplit(true)}
                  className="flex flex-col items-center gap-1.5 rounded-lg border border-dashed border-border px-2 py-3 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted"
                >
                  <Split className="size-5" />
                  {tr("تقسيم الدفع")}
                </button>
              </div>

              {method === "cash" ? (
                <div className="space-y-3">
                  <label htmlFor="pos-received" className="text-sm font-medium">
                    {tr("المبلغ اللي استلمته")}
                  </label>
                  <div className="relative">
                    <Input
                      id="pos-received"
                      autoFocus
                      type="number"
                      inputMode="decimal"
                      min="0"
                      step="0.5"
                      value={received}
                      onChange={(e) => {
                        setReceived(e.target.value);
                        setError(undefined);
                      }}
                      placeholder={egpNumber(total)}
                      className="h-12 pe-12 text-lg font-semibold tabular-nums"
                    />
                    <span className="pointer-events-none absolute inset-e-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">
                      {tr("ج.م")}
                    </span>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {quickCashAmounts(total).map((amount, i) => (
                      <Button
                        key={amount}
                        type="button"
                        variant="outline"
                        size="sm"
                        className="h-8 tabular-nums"
                        onClick={() => setReceived(String(amount))}
                      >
                        {i === 0 ? tr("المبلغ بالظبط") : egpNumber(amount * 100)}
                      </Button>
                    ))}
                  </div>
                  <div
                    className={cn(
                      "flex items-center justify-between rounded-lg px-4 py-3",
                      short > 0 ? "bg-destructive/10 text-destructive" : "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400",
                    )}
                    aria-live="polite"
                  >
                    <span className="text-sm font-medium">{short > 0 ? tr("ناقص") : tr("الباقي للعميل")}</span>
                    <span className="text-2xl font-bold tabular-nums">{egp(short > 0 ? short : change)}</span>
                  </div>
                </div>
              ) : (
                <div className="space-y-1.5">
                  <label htmlFor="pos-reference" className="text-sm font-medium">
                    {tr("رقم العملية")}{" "}<span className="text-xs font-normal text-muted-foreground">{tr("(اختياري)")}</span>
                  </label>
                  <Input
                    id="pos-reference"
                    autoFocus
                    dir="ltr"
                    value={reference}
                    onChange={(e) => setReference(e.target.value)}
                    placeholder={tr("آخر ٤ أرقام أو رقم التحويل")}
                    className="h-10"
                  />
                </div>
              )}
            </>
          ) : (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <p className="text-sm font-medium">{tr("تقسيم على أكتر من طريقة")}</p>
                <button type="button" onClick={() => setSplit(false)} className="text-xs text-primary hover:underline">
                  {tr("رجوع لطريقة واحدة")}
                </button>
              </div>
              {entries.map((entry, i) => (
                <div key={i} className="flex items-center gap-2">
                  <select
                    value={entry.paymentMethod}
                    onChange={(e) => setEntry(i, { paymentMethod: e.target.value })}
                    aria-label={tr("طريقة الدفع")}
                    className="h-10 rounded-md border border-input bg-background px-2 text-sm"
                  >
                    {METHODS.map((m) => (
                      <option key={m.key} value={m.key}>
                        {m.label}
                      </option>
                    ))}
                  </select>
                  <Input
                    type="number"
                    inputMode="decimal"
                    min="0"
                    step="0.5"
                    value={entry.amount}
                    onChange={(e) => setEntry(i, { amount: e.target.value })}
                    onFocus={() => {
                      if (!entry.amount && splitRemaining > 0) setEntry(i, { amount: String(splitRemaining / 100) });
                    }}
                    placeholder="0"
                    aria-label={tr("المبلغ")}
                    className="h-10 flex-1 tabular-nums"
                  />
                  {entries.length > 2 && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="size-9 text-muted-foreground"
                      onClick={() => setEntries((prev) => prev.filter((_, j) => j !== i))}
                      aria-label={tr("شيل")}
                    >
                      <Trash2 className="size-4" />
                    </Button>
                  )}
                </div>
              ))}
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="gap-1.5 text-muted-foreground"
                onClick={() => setEntries((prev) => [...prev, { paymentMethod: "cash", amount: "", reference: "" }])}
              >
                <Plus className="size-4" />
                {tr("طريقة كمان")}
              </Button>
              <dl className="space-y-1 rounded-lg bg-muted/50 px-4 py-3 text-sm" aria-live="polite">
                <div className="flex justify-between">
                  <dt className="text-muted-foreground">{tr("المدفوع")}</dt>
                  <dd className="font-medium tabular-nums">{egp(splitPaid)}</dd>
                </div>
                <div className="flex justify-between">
                  <dt className="text-muted-foreground">{splitChange > 0 ? tr("الباقي للعميل") : tr("المتبقي")}</dt>
                  <dd className={cn("font-bold tabular-nums", splitRemaining > 0 ? "text-destructive" : "text-emerald-700 dark:text-emerald-400")}>
                    {egp(splitChange > 0 ? splitChange : splitRemaining)}
                  </dd>
                </div>
              </dl>
            </div>
          )}

          {error && (
            <p role="alert" className="text-sm font-medium text-destructive">
              {error}
            </p>
          )}

          <Button type="submit" size="lg" className="h-12 w-full gap-2 text-base font-semibold" disabled={loading}>
            {loading && <Loader2 className="size-5 animate-spin" />}
            {loading ? tr("جاري الحفظ...") : tr("تأكيد البيع")}
          </Button>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useTransition } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ClockIcon } from "lucide-react";
import { OpenShiftAction, CloseShiftAction } from "@/actions/pos/shift.actions";
import { intlLocale, tdir, tr, trv } from "@/lib/i18n/dashboard";

type ActiveShift = {
  id: string;
  openingBalance: number;
  totalSales: number;
  transactionCount: number;
  openedAt: string;
};

type Props = {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  activeShift: ActiveShift | null;
  cashierName: string;
  onShiftOpened: (shift: ActiveShift) => void;
  onShiftClosed: () => void;
};

export default function ShiftModal({ open, onOpenChange, activeShift, cashierName, onShiftOpened, onShiftClosed }: Props) {
  const [openingBalance, setOpeningBalance] = useState("");
  const [closingBalance, setClosingBalance] = useState("");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [isPending, start] = useTransition();
  const [confirmClose, setConfirmClose] = useState(false);
  const [now] = useState(() => Date.now());

  const handleOpen = () => {
    setError(null);
    start(async () => {
      try {
        const val = parseFloat(openingBalance || "0");
        const shift = await OpenShiftAction(val);
        onShiftOpened({
          id: shift.id,
          openingBalance: shift.openingBalance,
          totalSales: shift.totalSales,
          transactionCount: shift.transactionCount,
          openedAt: shift.openedAt.toISOString(),
        });
        setOpeningBalance("");
      } catch (e: unknown) {
        setError(e instanceof Error ? e.message : tr("حدث خطأ"));
      }
    });
  };

  const handleClose = () => {
    if (!activeShift) return;
    setError(null);
    start(async () => {
      try {
        await CloseShiftAction({
          shiftId: activeShift.id,
          closingBalance: parseFloat(closingBalance || "0"),
          notes: notes || undefined,
        });
        onShiftClosed();
        setClosingBalance("");
        setNotes("");
        setConfirmClose(false);
      } catch (e: unknown) {
        setError(e instanceof Error ? e.message : tr("حدث خطأ"));
      }
    });
  };

  const openedAt = activeShift ? new Date(activeShift.openedAt) : null;
  const duration = openedAt ? Math.floor((now - openedAt.getTime()) / 60000) : 0;
  const expectedCash = activeShift
    ? activeShift.openingBalance + activeShift.totalSales
    : 0;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md" dir={tdir()}>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ClockIcon className="size-4" />
            {activeShift ? tr("إدارة الوردية") : tr("فتح وردية جديدة")}
          </DialogTitle>
        </DialogHeader>

        {!activeShift ? (
          /* Open Shift */
          <div className="space-y-4">
            <p className="text-sm text-muted-foreground">
              {tr("الكاشير:")}{" "}<span className="font-medium text-foreground">{cashierName}</span>
            </p>

            <div className="space-y-1.5">
              <label className="text-sm font-medium">{tr("رصيد الدرج الافتتاحي (ج)")}</label>
              <input
                type="number"
                min="0"
                step="0.5"
                value={openingBalance}
                onChange={(e) => setOpeningBalance(e.target.value)}
                placeholder="0.00"
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
              />
              <p className="text-xs text-muted-foreground">{tr("اتركه فارغاً إذا لم يكن هناك رصيد ابتدائي")}</p>
            </div>

            {error && <p className="text-sm text-destructive">{error}</p>}

            <Button className="w-full" onClick={handleOpen} disabled={isPending}>
              {isPending ? tr("جاري الفتح...") : tr("فتح الوردية")}
            </Button>
          </div>
        ) : !confirmClose ? (
          /* Shift Info */
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <Badge className="bg-emerald-500/10 text-emerald-600 border-emerald-200">
                <span className="size-1.5 rounded-full bg-emerald-500 inline-block me-1.5" />
                {tr("وردية مفتوحة")}
              </Badge>
              <span className="text-xs text-muted-foreground">
                {tr("{0} ({1} دقيقة)", openedAt?.toLocaleTimeString(intlLocale()), duration)}
              </span>
            </div>

            <div className="grid grid-cols-3 gap-3">
              <div className="rounded-lg border bg-muted/30 p-3 text-center">
                <p className="text-xs text-muted-foreground">{tr("رصيد الافتتاح")}</p>
                <p className="text-sm font-bold">{tr("{0} ج", (activeShift.openingBalance / 100).toFixed(0))}</p>
              </div>
              <div className="rounded-lg border bg-muted/30 p-3 text-center">
                <p className="text-xs text-muted-foreground">{tr("إجمالي المبيعات")}</p>
                <p className="text-sm font-bold text-primary">{tr("{0} ج", (activeShift.totalSales / 100).toFixed(0))}</p>
              </div>
              <div className="rounded-lg border bg-muted/30 p-3 text-center">
                <p className="text-xs text-muted-foreground">{tr("الفواتير")}</p>
                <p className="text-sm font-bold">{activeShift.transactionCount}</p>
              </div>
            </div>

            <div className="rounded-md bg-amber-50 border border-amber-200 px-3 py-2 text-sm">
              <span className="text-amber-700">{tr("النقدية المتوقعة:")}{" "}</span>
              <span className="font-bold text-amber-800">{tr("{0} ج", (expectedCash / 100).toFixed(0))}</span>
            </div>

            {error && <p className="text-sm text-destructive">{error}</p>}

            <div className="flex gap-2">
              <Button
                variant="outline"
                className="flex-1"
                onClick={() => onOpenChange(false)}
              >
                {tr("إغلاق النافذة")}
              </Button>
              <Button
                variant="destructive"
                className="flex-1"
                onClick={() => setConfirmClose(true)}
              >
                {tr("إغلاق الوردية")}
              </Button>
            </div>
          </div>
        ) : (
          /* Close Shift */
          <div className="space-y-4">
            <div className="rounded-md bg-amber-50 border border-amber-200 px-3 py-2 text-sm space-y-1">
              <div className="flex justify-between">
                <span className="text-muted-foreground">{tr("إجمالي المبيعات:")}</span>
                <span className="font-bold">{tr("{0} ج", (activeShift.totalSales / 100).toFixed(0))}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">{tr("النقدية المتوقعة في الدرج:")}</span>
                <span className="font-bold">{tr("{0} ج", (expectedCash / 100).toFixed(0))}</span>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium">{tr("النقدية الفعلية في الدرج (ج)")}</label>
              <input
                type="number"
                min="0"
                step="0.5"
                value={closingBalance}
                onChange={(e) => setClosingBalance(e.target.value)}
                placeholder={`${(expectedCash / 100).toFixed(0)}`}
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
              />
              {closingBalance && (
                <p className={`text-xs font-medium ${
                  parseFloat(closingBalance) * 100 >= expectedCash ? "text-emerald-600" : "text-destructive"
                }`}>
                  {parseFloat(closingBalance) * 100 >= expectedCash
                    ? tr("زيادة: +{0} ج", ((parseFloat(closingBalance) * 100 - expectedCash) / 100).toFixed(0))
                    : tr("عجز: −{0} ج", ((expectedCash - parseFloat(closingBalance) * 100) / 100).toFixed(0))
                  }
                </p>
              )}
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium">{tr("ملاحظات (اختياري)")}</label>
              <textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                rows={2}
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm resize-none focus:outline-none focus:ring-2 focus:ring-primary/50"
              />
            </div>

            {error && <p className="text-sm text-destructive">{error}</p>}

            <div className="flex gap-2">
              <Button variant="outline" className="flex-1" onClick={() => setConfirmClose(false)}>
                {tr("رجوع")}
              </Button>
              <Button variant="destructive" className="flex-1" onClick={handleClose} disabled={isPending}>
                {isPending ? tr("جاري الإغلاق...") : tr("تأكيد إغلاق الوردية")}
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Plus, Search } from "lucide-react";
import { GetOrderForReturnAction, ProcessReturnAction } from "@/actions/pos/returns.actions";
import { useRouter } from "next/navigation";
import { intlLocale, tdir, tr, trv } from "@/lib/i18n/dashboard";

type OrderItem = {
  id: string;
  productId: string;
  quantity: number;
  price: number;
  product: { id: string; name: string; image: string; sku: string | null };
};

type Order = {
  id: string;
  fullName: string;
  createdAt: Date;
  total: number;
  items: OrderItem[];
  posReturns: { items: { productId: string; quantity: number }[] }[];
};

export default function ReturnsClient({ storeId: _storeId }: { storeId: string }) {
  const [open, setOpen] = useState(false);
  const [orderId, setOrderId] = useState("");
  const [order, setOrder] = useState<Order | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [returnItems, setReturnItems] = useState<Record<string, number>>({});
  const [returnType, setReturnType] = useState<"FULL_RETURN" | "PARTIAL_RETURN">("PARTIAL_RETURN");
  const [reason, setReason] = useState("");
  const [refundMethod, setRefundMethod] = useState("cash");
  const [isPending, start] = useTransition();
  const router = useRouter();

  const loadOrder = async () => {
    if (!orderId.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const data = await GetOrderForReturnAction(orderId.trim());
      setOrder(data as Order);
      // Initialize return quantities to 0
      const initial: Record<string, number> = {};
      data.items.forEach((item) => { initial[item.productId] = 0; });
      setReturnItems(initial);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : tr("طلب غير موجود"));
    } finally {
      setLoading(false);
    }
  };

  const getReturnableQty = (item: OrderItem) => {
    const alreadyReturned = order?.posReturns
      .flatMap((r) => r.items)
      .filter((i) => i.productId === item.productId)
      .reduce((sum, i) => sum + i.quantity, 0) ?? 0;
    return item.quantity - alreadyReturned;
  };

  const refundAmount = order
    ? order.items.reduce((sum, item) => {
        const qty = returnItems[item.productId] ?? 0;
        return sum + item.price * qty;
      }, 0)
    : 0;

  const handleSubmit = () => {
    if (!order) return;
    const itemsToReturn = order.items
      .filter((item) => (returnItems[item.productId] ?? 0) > 0)
      .map((item) => ({
        productId: item.productId,
        quantity: returnItems[item.productId]!,
        unitPrice: item.price,
        reason,
      }));

    if (itemsToReturn.length === 0) {
      setError(tr("اختر على الأقل منتج واحد للإرجاع"));
      return;
    }

    start(async () => {
      try {
        await ProcessReturnAction({
          originalOrderId: order.id,
          type: returnType,
          items: itemsToReturn,
          reason,
          refundMethod,
        });
        setOpen(false);
        setOrder(null);
        setOrderId("");
        router.refresh();
      } catch (e: unknown) {
        setError(e instanceof Error ? e.message : tr("حدث خطأ"));
      }
    });
  };

  return (
    <>
      <Button onClick={() => setOpen(true)} className="gap-1.5">
        <Plus className="size-4" />
        {tr("إرجاع جديد")}
      </Button>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-lg" dir={tdir()}>
          <DialogHeader>
            <DialogTitle>{tr("معالجة مرتجع")}</DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            {/* Order search */}
            <div className="flex gap-2">
              <input
                value={orderId}
                onChange={(e) => setOrderId(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && loadOrder()}
                placeholder={tr("رقم الطلب...")}
                className="flex-1 rounded-md border border-input bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
              />
              <Button onClick={loadOrder} disabled={loading} size="sm" className="gap-1.5">
                <Search className="size-3.5" />
                {tr("بحث")}
              </Button>
            </div>

            {error && <p className="text-sm text-destructive">{error}</p>}

            {order && (
              <>
                {/* Order info */}
                <div className="rounded-md bg-muted/50 px-3 py-2 text-sm">
                  <span className="font-medium">{order.fullName}</span>
                  <span className="text-muted-foreground ms-2">
                    {tr("{0} · {1} ج", new Date(order.createdAt).toLocaleDateString(intlLocale()), (order.total / 100).toFixed(0))}
                  </span>
                </div>

                {/* Return type */}
                <div className="flex gap-2">
                  {(["FULL_RETURN", "PARTIAL_RETURN"] as const).map((t) => (
                    <button
                      key={t}
                      onClick={() => {
                        setReturnType(t);
                        if (t === "FULL_RETURN") {
                          const full: Record<string, number> = {};
                          order.items.forEach((i) => { full[i.productId] = getReturnableQty(i); });
                          setReturnItems(full);
                        }
                      }}
                      className={`flex-1 rounded-md border py-1.5 text-sm font-medium transition-colors ${
                        returnType === t ? "bg-primary text-primary-foreground border-primary" : "border-border hover:bg-muted"
                      }`}
                    >
                      {t === "FULL_RETURN" ? tr("إرجاع كامل") : tr("إرجاع جزئي")}
                    </button>
                  ))}
                </div>

                {/* Items */}
                <div className="space-y-2 max-h-48 overflow-y-auto">
                  {order.items.map((item) => {
                    const returnable = getReturnableQty(item);
                    return (
                      <div key={item.productId} className="flex items-center justify-between rounded-md border p-2">
                        <div className="min-w-0 flex-1">
                          <p className="text-sm font-medium truncate">{item.product.name}</p>
                          <p className="text-xs text-muted-foreground">
                            {tr("قابل للإرجاع: {0} من {1}", returnable, item.quantity)}
                          </p>
                        </div>
                        <div className="flex items-center gap-1.5 ms-2">
                          <button
                            onClick={() => setReturnItems((prev) => ({ ...prev, [item.productId]: Math.max(0, (prev[item.productId] ?? 0) - 1) }))}
                            className="flex size-6 items-center justify-center rounded border text-sm"
                          >
                            −
                          </button>
                          <span className="w-6 text-center text-sm font-bold">
                            {returnItems[item.productId] ?? 0}
                          </span>
                          <button
                            onClick={() => setReturnItems((prev) => ({ ...prev, [item.productId]: Math.min(returnable, (prev[item.productId] ?? 0) + 1) }))}
                            disabled={returnable === 0}
                            className="flex size-6 items-center justify-center rounded border text-sm disabled:opacity-40"
                          >
                            +
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>

                {/* Reason */}
                <input
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  placeholder={tr("سبب الإرجاع (اختياري)")}
                  className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:outline-none"
                />

                {/* Refund method */}
                <select
                  value={refundMethod}
                  onChange={(e) => setRefundMethod(e.target.value)}
                  className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:outline-none"
                >
                  <option value="cash">{tr("نقداً")}</option>
                  <option value="card">{tr("بطاقة")}</option>
                  <option value="store_credit">{tr("رصيد بالمتجر")}</option>
                </select>

                {refundAmount > 0 && (
                  <div className="rounded-md bg-amber-50 border border-amber-200 px-3 py-2 text-center">
                    <p className="text-xs text-amber-700">{tr("مبلغ الاسترداد")}</p>
                    <p className="text-xl font-bold text-amber-800">{tr("{0} ج", (refundAmount / 100).toFixed(0))}</p>
                  </div>
                )}

                <Button
                  className="w-full"
                  onClick={handleSubmit}
                  disabled={isPending || refundAmount === 0}
                >
                  {isPending ? tr("جاري المعالجة...") : tr("تأكيد الإرجاع")}
                </Button>
              </>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}
